CARDIO.register({"item":"d114","meta":{"num":"d114","label":"114","spe":"dermato","short":"Exanthème, érythrodermie","title":"Exanthème et érythrodermie de l'enfant et de l'adulte (items 114 et 164)","section":"D","chapter":4,"pages":"82-93","sdd":[{"num":37,"label":"Éruptions chez l'enfant"},{"num":85,"label":"Érythème"},{"num":88,"label":"Prurit"},{"num":178,"label":"Demande/prescription raisonnée et choix d'un examen diagnostique"},{"num":219,"label":"Hyperéosinophilie"},{"num":235,"label":"Découverte, diagnostic positif, dépistage rapide VIH"},{"num":310,"label":"Prévention chez un malade contagieux"}]},"objectives":[{"id":"d114-obj-01","rank":"A","rubric":"Définition","title":"Définition d'un exanthème","desc":"Érythème d'apparition brutale et transitoire"},{"id":"d114-obj-02","rank":"A","rubric":"Définition","title":"Définition d'une érythrodermie","desc":"Érythème, plus de 90 % de la surface corporelle, évolution d'au moins 6 semaines, prurit, desquamation, altération de l'état général"},{"id":"d114-obj-03","rank":"A","rubric":"Diagnostic positif","title":"Reconnaître les trois types séméiologiques d'exanthème","desc":"Exanthème roséoliforme, morbilliforme, scarlatiniforme"},{"id":"d114-obj-04","rank":"B","rubric":"Diagnostic positif","title":"Reconnaître l'éruption du mégalérythème épidémique","desc":"Atteinte œdémateuse du visage, éruption en gants et chaussettes"},{"id":"d114-obj-05","rank":"B","rubric":"Diagnostic positif","title":"Reconnaître le rash à l'ampicilline lors d'une infection à Epstein-Barr virus","desc":"Complication classique ne devant pas être confondue avec une toxidermie aux pénicillines"},{"id":"d114-obj-06","rank":"A","rubric":"Diagnostic positif","title":"Connaître les complications systémiques de l'érythrodermie","desc":"Complications hydro-électrolytiques, infectieuses, de décubitus, décompensation de tares sous-jacentes, décès"},{"id":"d114-obj-07","rank":"A","rubric":"Diagnostic positif","title":"Savoir diagnostiquer une épidermolyse staphylococcique","desc":"Terrain (nouveau-né et jeune enfant), infection du cordon et impétigo, fièvre et altération de l'état général, lésions péri-orificielles, décollements bulleux"},{"id":"d114-obj-08","rank":"A","rubric":"Identifier une urgence","title":"Connaître les signes cliniques du syndrome de Kawasaki","desc":"Terrain, fièvre, adénopathies, atteinte caractéristique des muqueuses"},{"id":"d114-obj-09","rank":"A","rubric":"Identifier une urgence","title":"Savoir que l'érythrodermie est une urgence et savoir la prendre en charge","desc":"Hospitalisation et mise en condition du malade (réchauffement, rééquilibration hydro-électrolytique, détecter l'infection...)"},{"id":"d114-obj-10","rank":"A","rubric":"Étiologies","title":"Connaître la principale cause d'exanthème chez l'enfant et chez l'adulte","desc":"Origine virale"},{"id":"d114-obj-11","rank":"B","rubric":"Étiologies","title":"Connaître les trois causes d'exanthème à évoquer systématiquement chez l'adulte","desc":"VIH, syphilis, médicaments"},{"id":"d114-obj-12","rank":"B","rubric":"Étiologies","title":"Connaître les quatre causes principales d'exanthème roséoliforme","desc":"Exanthème subit, rubéole, primo-infection VIH, syphilis secondaire"},{"id":"d114-obj-13","rank":"B","rubric":"Étiologies","title":"Connaître les trois causes principales d'exanthème morbilliforme","desc":"Rougeole, mégalérythème épidémique, mononucléose infectieuse"},{"id":"d114-obj-14","rank":"B","rubric":"Étiologies","title":"Connaître les deux causes principales d'exanthème scarlatiniforme","desc":"Scarlatine, syndrome de Kawasaki"},{"id":"d114-obj-15","rank":"B","rubric":"Étiologies","title":"Connaître les quatre principaux exanthèmes à risque chez la femme enceinte","desc":"Rubéole (mort fœtale ou malformations), parvovirus B19 (anasarque fœtale), toxoplasmose, syphilis (forme congénitale)"},{"id":"d114-obj-16","rank":"A","rubric":"Étiologies","title":"Savoir évoquer une rougeole chez l'enfant et chez l'adulte","desc":""},{"id":"d114-obj-17","rank":"A","rubric":"Étiologies","title":"Connaître trois causes d'érythrodermie chez l'adulte","desc":"Psoriasis, eczéma, syndrome de Sézary, toxidermie (DRESS), VIH, gale hyperkératosique"},{"id":"d114-obj-18","rank":"B","rubric":"Contenu multimédia","title":"Reconnaître une langue framboisée","desc":"Image : langue framboisée"},{"id":"d114-obj-19","rank":"A","rubric":"Contenu multimédia","title":"Reconnaître un exanthème morbilliforme","desc":""},{"id":"d114-obj-20","rank":"A","rubric":"Contenu multimédia","title":"Reconnaître un exanthème scarlatiniforme","desc":""},{"id":"d114-obj-21","rank":"A","rubric":"Contenu multimédia","title":"Reconnaître une érythrodermie","desc":"Image d'érythrodermie"},{"id":"d114-obj-22","rank":"B","rubric":"Contenu multimédia","title":"Reconnaître un mégalérythème","desc":"Image de mégalérythème chez l'enfant"},{"id":"d114-obj-23","rank":"A","rubric":"Diagnostic positif","title":"Exanthèmes fébriles de l'enfant : type d'éruption","desc":""},{"id":"d114-obj-24","rank":"A","rubric":"Identifier une urgence","title":"Exanthèmes fébriles de l'enfant : évaluation de la gravité","desc":""},{"id":"d114-obj-25","rank":"A","rubric":"Diagnostic positif","title":"Exanthèmes fébriles de l'enfant : orientation diagnostique","desc":""},{"id":"d114-obj-26","rank":"A","rubric":"Étiologies","title":"Maladies infectieuses éruptives : rougeole","desc":"Épidémiologie (A), prévention (A), caractéristiques cliniques (A), signes de gravité (A), complications (A), principes de conduite à tenir autour d'un cas (A)"},{"id":"d114-obj-27","rank":"A","rubric":"Étiologies","title":"Maladies infectieuses éruptives : rubéole","desc":"Épidémiologie (B), prévention (A), caractéristiques cliniques (A), risque particulier en cours de grossesse (A), fœtopathie (B)"},{"id":"d114-obj-28","rank":"A","rubric":"Étiologies","title":"Maladies infectieuses éruptives : mégalérythème épidémique","desc":"Épidémiologie (B), caractéristiques cliniques (A), risque pour femme enceinte (A)"},{"id":"d114-obj-29","rank":"A","rubric":"Étiologies","title":"Maladies infectieuses éruptives : exanthème subit","desc":"Épidémiologie (B), caractéristiques cliniques (A)"},{"id":"d114-obj-30","rank":"A","rubric":"Étiologies","title":"Maladies infectieuses éruptives : mononucléose infectieuse","desc":"Épidémiologie (A), caractéristiques cliniques (A), signes de gravité, complications (A), diagnostic différentiel (A), évolution naturelle (B)"},{"id":"d114-obj-31","rank":"A","rubric":"Étiologies","title":"Maladies infectieuses éruptives : scarlatine","desc":"Épidémiologie (A), caractéristiques cliniques (A), complications et orientation (A), éviction scolaire (A)"},{"id":"d114-obj-32","rank":"A","rubric":"Étiologies","title":"Maladies infectieuses éruptives : maladie de Kawasaki","desc":"Épidémiologie (B), caractéristiques cliniques (A), orientation (hospitalisation) (A), prise en charge (B)"},{"id":"d114-obj-33","rank":"A","rubric":"Étiologies","title":"Maladies infectieuses éruptives : varicelle","desc":"Épidémiologie (A), caractéristiques cliniques (A), contre-indication aspirine (A), complications (A), connaître les sujets à risque (A)"}],"course":{"sections":[{"id":"d114-sec-01","title":"Exanthème : définition, démarche, bilan","rank":"A","objectives":["d114-obj-01","d114-obj-10","d114-obj-11","d114-obj-23","d114-obj-24","d114-obj-25"],"content":"### Définition\n- **Exanthème** = **érythème d'apparition brutale et transitoire** : intense ou non, diffus ou de siège particulier, isolé ou accompagné d'autres signes ; une atteinte des muqueuses (**énanthème**) peut s'y associer ; **bénin ou potentiellement grave**.\n- **2 causes principales** : **infectieuses** et **médicamenteuses**. Chez l'**enfant**, les causes infectieuses sont surtout **virales** ; chez l'**adulte**, ce sont notamment des infections sexuellement transmissibles : **syphilis**, **VIH** (virus de l'immunodéficience humaine).\n\n### Démarche devant un exanthème\n1. **Anamnèse** : contexte **épidémique**, **contage** possible, **prise de médicament**.\n2. **Type d'éruption** : roséoliforme, morbilliforme ou scarlatiniforme (section suivante).\n3. **Signes associés** :\n   - origine **virale** : **fièvre**, **syndrome grippal**, **énanthème**, **polyadénopathie** ;\n   - origine **médicamenteuse** : **prurit**, éruption **polymorphe**, **hyperéosinophilie** sanguine.\n\n### Gravité [B]\n- Exanthème diffus **scarlatiniforme**, **fébrile**, d'apparition **brutale** → rechercher un **choc toxique staphylococcique** et des signes de **retentissement hémodynamique**.\n\n### Bilan [B]\n- **Enfant** : **aucun examen** indispensable, sauf suspicion de **scarlatine** (numération-formule sanguine ou NFS, prélèvement de gorge) ou de **Kawasaki** (NFS, plaquettes, échographie cardiaque).\n- **Adulte** (sans cause évidente) : NFS, tests hépatiques, sérodiagnostic de mononucléose, **test tréponémique**, **charge virale VIH** et sérologie VIH combinée.\n- **Femme enceinte** : sérologies de **toxoplasmose, rubéole, CMV (cytomégalovirus), parvovirus B19, syphilis**.","keyPoints":["**Exanthème** = **érythème brutal et transitoire** (± **énanthème**), bénin ou grave.","Causes : **virales** (surtout chez l'**enfant**) ; **VIH, syphilis** et **médicaments** chez l'**adulte**.","**Viral** : fièvre, syndrome grippal, énanthème, adénopathies. **Médicamenteux** : **prurit**, éruption **polymorphe**, **hyperéosinophilie**.","[B] Enfant : **pas d'examen** sauf **scarlatine** (gorge) ou **Kawasaki** (échographie cardiaque)."],"pitfalls":["Chez l'adulte, penser au **VIH**, à la **syphilis** et aux **médicaments** (toxidermie).","Exanthème = **brutal et transitoire** ; ne pas le confondre avec l'**érythrodermie** (durable : au moins 6 semaines)."],"src":"p. 84-85, 90"},{"id":"d114-sec-02","title":"Les 3 types d'exanthème et leurs causes","rank":"A","objectives":["d114-obj-03","d114-obj-12","d114-obj-13","d114-obj-14","d114-obj-19","d114-obj-20"],"content":"| Type | Aspect | Causes principales [B] |\n|---|---|---|\n| **Roséoliforme** (ou rubéoliforme) | **petites macules rosées, pâles, bien séparées** | **exanthème subit**, **rubéole**, **primo-infection VIH**, **syphilis secondaire** |\n| **Morbilliforme** | **maculo-papules rouges**, parfois **confluentes en plaques** séparées par de la **peau saine** | **rougeole**, **mégalérythème épidémique**, **mononucléose infectieuse** |\n| **Scarlatiniforme** | **plaques diffuses rouge vif**, un peu granitées au toucher, **sans peau saine** entre elles, chaudes ou cuisantes, **plus marquées dans les plis** ; desquamation secondaire en larges lambeaux possible | **scarlatine**, **syndrome de Kawasaki** |\n\n- [B] Autres causes d'exanthème **morbilliforme** : **primo-infection VIH**, **toxidermie** (bêta-lactamines, sulfamides, anticomitiaux, c'est-à-dire antiépileptiques), syndrome de Kawasaki.","keyPoints":["3 types : **roséoliforme** (petites macules rosées séparées), **morbilliforme** (maculo-papules, **peau saine** entre les plaques), **scarlatiniforme** (rouge vif, **sans peau saine**, plis).","[B] **Roséoliforme** : exanthème subit, rubéole, primo-infection VIH, syphilis secondaire.","[B] **Morbilliforme** : rougeole, mégalérythème épidémique, mononucléose infectieuse.","[B] **Scarlatiniforme** : scarlatine, syndrome de Kawasaki."],"pitfalls":["**Scarlatiniforme** = **aucun intervalle de peau saine** ; **morbilliforme** = **peau saine entre les plaques**."],"src":"p. 85-86, 88"},{"id":"d114-sec-03","title":"Roséoliforme : exanthème subit et rubéole","rank":"A","objectives":["d114-obj-12","d114-obj-15","d114-obj-27","d114-obj-29"],"content":"### Exanthème subit (roséole infantile)\n- **Primo-infection par le virus HHV6** (human herpesvirus 6), chez le **nourrisson de 6 à 18 mois**.\n- **Fièvre élevée (39-40 °C) isolée pendant 48-72 heures (3 jours)**, **puis** **éruption roséoliforme prédominant sur le tronc**, en une seule poussée.\n- **Pas d'éviction** de la collectivité recommandée.\n- Complications **rares** : convulsions fébriles, méningite virale, hépatite aiguë, pneumopathie, syndrome mononucléosique.\n\n### Rubéole\n- [B] **Épidémiologie** : virus de la rubéole ; âge de survenue **15 à 25 ans** ; incubation **3 semaines** ; contagiosité de **7 jours avant** à **14 jours après** le début de l'éruption.\n- **Clinique** : souvent **asymptomatique** ; **exanthème discret** (2 à 4 jours), **arthralgies**, **conjonctivite**.\n- **Femme enceinte non immunisée** : risque de **mort fœtale** ou de **malformations** neurologiques et sensorielles.\n- **Informer** le personnel, les parents et la femme enceinte.","keyPoints":["**Exanthème subit** : **nourrisson 6-18 mois**, **HHV6**, **fièvre isolée 3 jours** puis **éruption roséoliforme du tronc**.","Exanthème subit : **pas d'éviction** de la collectivité.","**Rubéole** (15-25 ans, souvent asymptomatique) : **exanthème discret**, arthralgies, conjonctivite.","**Rubéole chez une femme enceinte non immunisée** → **mort fœtale** ou **malformations** graves."],"pitfalls":["Nourrisson : éruption roséoliforme **après 3 jours de fièvre isolée** → **exanthème subit**.","Rubéole : le danger est pour la **femme enceinte non immunisée** (fœtus), pas pour l'enfant."],"src":"p. 85, 90"},{"id":"d114-sec-04","title":"Rougeole : exanthème morbilliforme typique","rank":"A","objectives":["d114-obj-16","d114-obj-19","d114-obj-26"],"content":"- **Évoquer une rougeole** devant l'association **catarrhe oculo-nasal + conjonctivite + exanthème fébrile**.\n- **Morbillivirus** (paramyxovirus) ; incubation **10-12 jours** ; contagiosité de **3-5 jours avant** à **4 jours après** l'éruption.\n\n### Déroulement\n1. **Phase pré-éruptive** : **fièvre élevée (39-40 °C)**, **catarrhe oculo-nasal**, **conjonctivite**, **signe de Köplick** (semis de papules sur la face interne des joues).\n2. **Exanthème morbilliforme** : début **derrière les oreilles (rétro-auriculaire)**, puis **extension à tout le corps en une seule poussée**.\n\n### Complications\n- **Pneumopathie**, **encéphalite** (grave), **kératite** (risque de cécité).\n\n### Conduite à tenir\n- **Maladie à déclaration obligatoire**.\n- **Éviction de la collectivité jusqu'à 5 jours après le début de l'éruption** ; informer le personnel et les parents.","keyPoints":["**Rougeole** = **catarrhe oculo-nasal + conjonctivite + exanthème fébrile** ; **signe de Köplick**.","Exanthème **morbilliforme** : début **rétro-auriculaire**, extension en **une seule poussée**.","Complications : **pneumopathie**, **encéphalite**, **kératite** (cécité).","**Déclaration obligatoire** ; **éviction jusqu'à 5 jours après le début de l'éruption**."],"pitfalls":["La rougeole est **contagieuse avant l'éruption** (3-5 jours avant) et jusqu'à **4 jours après**.","Le **signe de Köplick** (semis de papules sur la face interne des joues) apparaît en **phase pré-éruptive**."],"src":"p. 86, 90"},{"id":"d114-sec-05","title":"Morbilliforme : mégalérythème épidémique et mononucléose infectieuse","rank":"A","objectives":["d114-obj-04","d114-obj-05","d114-obj-13","d114-obj-15","d114-obj-22","d114-obj-28","d114-obj-30"],"content":"### Mégalérythème épidémique (parvovirus B19)\n- **Enfant de 5 à 10 ans** [B] ; incubation **14 jours** [B] ; contagiosité **limitée à la phase pré-éruptive** ; fièvre modérée.\n- **Visage** : érythème et **œdème des joues** (aspect « souffleté ») → puis **tronc** : érythème à **bords émiettés** (en guirlande) → **érythème en « gants et chaussettes »**. Arthralgies possibles.\n- **Grossesse** : **pas de risque tératogène** ; infection au 2e trimestre : risque d'**anasarque fœtale**, de myocardite et d'anémie fœtale. Autres personnes à risque de complications : **immunodéprimé**, patient avec **anémie chronique**.\n\n### Mononucléose infectieuse (MNI)\n- **Epstein-Barr virus (EBV)**, surtout chez l'**adolescent** ; incubation **4 à 6 semaines** ; contagiosité maximale pendant la **phase aiguë** (jusqu'à 6 mois).\n- **Fièvre**, **asthénie importante**, **polyadénopathie**, **splénomégalie** ; **lymphocytose élevée avec lymphocytes hyperbasophiles**.\n- **Exanthème inconstant (5-10 %)**, **sauf en cas de prescription de pénicilline A** : c'est le **rash à l'ampicilline**, à **ne pas confondre avec une toxidermie** aux pénicillines.\n- Complications **rares** : hépatite, méningo-encéphalite, **rupture splénique**, agranulocytose.","keyPoints":["**Mégalérythème épidémique** (**parvovirus B19**, enfant **5-10 ans**) : **joues œdémateuses**, tronc à **bords émiettés**, puis **gants et chaussettes**.","Parvovirus B19 et **grossesse** : **anasarque fœtale** (2e trimestre), **pas de risque tératogène**.","**MNI** (**EBV**, **adolescent**) : fièvre, asthénie, polyadénopathie, splénomégalie ; **lymphocytes hyperbasophiles**.","MNI : **exanthème inconstant** (5-10 %) **sauf sous pénicilline A** → **rash à l'ampicilline**, **pas une toxidermie**."],"pitfalls":["**Rash à l'ampicilline** d'une MNI : ne pas conclure à une **allergie** aux pénicillines (toxidermie).","Parvovirus B19 chez la femme enceinte : **pas tératogène**, mais risque d'**anasarque fœtale**."],"src":"p. 82, 86-87, 90"},{"id":"d114-sec-06","title":"Scarlatiniforme : scarlatine et scarlatine staphylococcique","rank":"A","objectives":["d114-obj-07","d114-obj-14","d114-obj-18","d114-obj-20","d114-obj-31"],"content":"### Scarlatine (streptocoque)\n- **Streptocoque du groupe A** (exotoxines) ; **enfant de 5 à 10 ans** ; incubation **2 à 4 jours** ; contamination **aérienne** ; contagiosité **2 à 3 semaines** (elle persiste 48 h après le début du traitement).\n- **Début brutal** : fièvre 39-40 °C, douleurs pharyngées, céphalées, **angine rouge**, adénopathies sous-maxillaires.\n- **Éruption** des **grands plis** (scarlatiniforme) ; **langue framboisée** (dépapillation progressive en « V ») ; puis desquamation fine ou en lambeaux.\n- **Prélèvement de gorge** ; **amoxicilline** ; **éviction scolaire jusqu'à 48 h après le début du traitement**.\n- **Complications post-streptococciques** : **glomérulonéphrite**, **rhumatisme articulaire aigu**.\n\n### Scarlatine staphylococcique (= épidermolyse staphylococcique)\n- **Staphylococcus aureus** sécréteur de toxines ; terrain : **nouveau-né, nourrisson, jeune enfant** ou **adulte immunodéprimé** ; contexte d'**infection du cordon** (nouveau-né) ou d'**impétigo**.\n- **Pas d'angine** ; fièvre et altération de l'état général ; éruption débutant aux **grands plis** et aux **régions péri-orificielles**, puis **décollement bulleux**.\n- Forme sévère : **choc toxique staphylococcique**. Traitement : **oxacilline** ; prélèvements bactériologiques.","keyPoints":["**Scarlatine** : **streptocoque A**, **5-10 ans**, début **brutal** + **angine**, éruption des **grands plis**, **langue framboisée**.","Scarlatine : **prélèvement de gorge**, **amoxicilline**, **éviction 48 h** après le début du traitement.","Complications **post-streptococciques** : **glomérulonéphrite**, **rhumatisme articulaire aigu**.","**Scarlatine staphylococcique** : **pas d'angine**, grands plis et zones péri-orificielles puis **décollement bulleux** ; **oxacilline**.","[B] **Exanthème scarlatiniforme fébrile brutal** → chercher un **choc toxique** staphylococcique."],"pitfalls":["**Pas d'angine** + éruption des plis puis **décollements bulleux** : **scarlatine staphylococcique**.","Antibiotique : **amoxicilline** (streptocoque) ≠ **oxacilline** (staphylocoque).","La **langue framboisée** se voit dans la **scarlatine** et dans le **Kawasaki**."],"src":"p. 88-90"},{"id":"d114-sec-07","title":"Syndrome de Kawasaki","rank":"A","objectives":["d114-obj-08","d114-obj-14","d114-obj-18","d114-obj-32"],"content":"- **Vasculite systémique aiguë** (syndrome adéno-cutanéo-muqueux) de l'**enfant de moins de 5 ans**.\n- **Diagnostic** : **au moins 5 critères sur 6** :\n  1. **fièvre élevée > 38,5 °C pendant plus de 5 jours**, avec altération de l'état général ;\n  2. **conjonctivite bilatérale** avec œdème des paupières ;\n  3. **énanthème** : **chéilite** et **langue framboisée** ;\n  4. **érythème et œdème des extrémités** ;\n  5. **exanthème polymorphe** ;\n  6. **lymphadénite**, souvent asymétrique.\n- Évolution : **desquamation en « doigt de gant »**.\n- [B] **Biologie** : syndrome inflammatoire (protéine C-réactive ou **CRP** élevée), **hyperleucocytose à polynucléaires neutrophiles**, **thrombocytose**. Bilan : NFS, plaquettes, **échographie cardiaque**.\n\n### Gravité\n- **Complications cardiaques** : **anévrismes coronariens** (surtout en cas de **retard thérapeutique**), troubles du rythme, décès par myocardite ou infarctus.\n- **Hospitalisation indispensable**.","keyPoints":["**Kawasaki** : **vasculite** aiguë de l'**enfant < 5 ans**, **fièvre > 38,5 °C pendant plus de 5 jours**.","Diagnostic : **≥ 5 critères sur 6** (fièvre, conjonctivite bilatérale, chéilite + langue framboisée, érythème et œdème des extrémités, exanthème polymorphe, lymphadénite).","Risque : **anévrismes coronariens** (retard thérapeutique) → **hospitalisation indispensable**.","[B] Syndrome inflammatoire (CRP élevée), hyperleucocytose à polynucléaires neutrophiles, **thrombocytose** ; **échographie cardiaque**."],"pitfalls":["Fièvre **> 5 jours** + **conjonctivite bilatérale** + lèvres/langue framboisée chez un enfant **< 5 ans** : penser **Kawasaki**, **hospitaliser** (risque coronarien).","Ne pas oublier que la **langue framboisée** existe aussi dans la **scarlatine**."],"src":"p. 88, 90"},{"id":"d114-sec-08","title":"Érythrodermie : définir et reconnaître","rank":"A","objectives":["d114-obj-02","d114-obj-21"],"content":"- **Érythrodermie** = syndrome **rare**, **diagnostiqué cliniquement** : **érythème confluent + desquamation** sur **plus de 90 % de la surface corporelle**, **depuis au moins 6 semaines**.\n- **Urgence dermatologique** : prise en charge **immédiate** (traitement et recherche de la cause) ; **hospitalisation** dans un service spécialisé.\n- L'aspect clinique **ne préjuge pas de la cause**.\n\n### Signes cliniques\n- **Érythème généralisé**, inflammatoire, **plus violacé dans les zones déclives**, dont l'intensité **varie d'un jour à l'autre**.\n- **Desquamation constante** (fine ou en larges lambeaux).\n- **Prurit constant** et **dysrégulation thermique** (épisodes de **fièvre** et d'**hypothermie**).\n- **Pachydermie** (visible dans les plis), **œdème du visage** (ectropion possible), atteinte des **muqueuses** (chéilite, conjonctivite, stomatite).\n- Après quelques semaines : chute des **cheveux, sourcils, cils** ; **ongles** dystrophiques (ligne de Beau).\n- **Polyadénopathie** fréquente ; pertes **hydro-électrolytiques et/ou protéiques** ; **altération de l'état général**.\n\n### Ce qui n'est PAS une érythrodermie\n- Une éruption érythémato-squameuse faite d'éléments multiples **séparés par de la peau saine**.\n- Un **exanthème** ou une **nécrolyse épidermique** décollante, d'évolution **aiguë**.","keyPoints":["**Érythrodermie** = **érythème + desquamation** sur **> 90 %** de la surface corporelle, **depuis ≥ 6 semaines**.","**Prurit constant**, **dysrégulation thermique** (fièvre, hypothermie), **pachydermie**, **œdème du visage**, polyadénopathie.","**Urgence** : **hospitalisation** en service spécialisé ; l'aspect clinique ne donne **pas la cause**.","**≠ exanthème** (aigu) ; **≠ éruption à éléments séparés par de la peau saine**."],"pitfalls":["L'érythrodermie **n'est pas synonyme d'érythème ni d'exanthème**.","Elle est **durable** (≥ 6 semaines) : un exanthème aigu, même diffus, n'en est pas une."],"src":"p. 90-91, 93"},{"id":"d114-sec-09","title":"Érythrodermie : causes et bilan étiologique","rank":"A","objectives":["d114-obj-17"],"content":"### Causes principales (adulte)\n| Groupe | Causes |\n|---|---|\n| **Dermatoses inflammatoires** | **psoriasis** (+++), **eczéma / dermatite atopique** (+++), **toxidermie : DRESS** (Drug Rash with hyper-Eosinophilia and Systemic Symptoms) (+++), lichen plan [B] |\n| **Lymphome** | **syndrome de Sézary** (+++) = lymphome T cutané épidermotrope |\n| **Infections** | **VIH** (+), **gale croûteuse** (++) |\n| Sans cause [B] | **idiopathique** : 10 à 15 % des cas |\n\n- **Enfant** : nouveau-né et nourrisson de moins de 3 mois : maladie de Leiner-Moussous ; après 3 mois : **dermatite atopique** (+++), puis mêmes causes que l'adulte.\n\n### Chercher la cause\n- **Interrogatoire** : ancienneté de l'éruption, antécédents dermatologiques et généraux, **prise de médicament**, traitements locaux utilisés, **contexte infectieux**.\n- **Biopsie cutanée** : peut montrer des signes de la maladie en cause ; **à répéter** si l'on suspecte un **lymphome cutané**.\n- **Prélèvements bactériologiques ou parasitologiques** si besoin (fièvre, complications infectieuses).","keyPoints":["Causes : **psoriasis**, **dermatite atopique/eczéma**, **toxidermie (DRESS)**, **syndrome de Sézary** ; aussi **VIH**, **gale croûteuse**.","**Biopsie cutanée** : à **répéter** si suspicion de **lymphome cutané**.","**Interrogatoire** : ancienneté, antécédents, **médicaments**, traitements locaux, contexte infectieux.","[B] **10 à 15 %** d'érythrodermies **idiopathiques**."],"pitfalls":["Ne pas oublier la **toxidermie (DRESS)** : toujours chercher une **prise médicamenteuse**.","Le **syndrome de Sézary** est un **lymphome** : biopsie **répétée** si doute."],"src":"p. 91-92"},{"id":"d114-sec-10","title":"Érythrodermie : complications et prise en charge","rank":"A","objectives":["d114-obj-06","d114-obj-09"],"content":"### Complications\nLa gravité dépend du **terrain** et des **complications**.\n- **Hydro-électrolytiques** : pertes dues à la vasodilatation cutanée, à la desquamation, au suintement, à l'œdème et à la fièvre ; elles peuvent **décompenser** une insuffisance cardiaque, respiratoire ou rénale.\n- **Décubitus** : dénutrition, cachexie, **escarres**.\n- **Infectieuses** : infections cutanées bactériennes (**staphylocoque**) ou virales (**herpès**, varicelle-zona) ; infections générales (**pneumopathies, septicémies**).\n- **Décès** : mortalité **jusqu'à 20 %**, liée aux complications, surtout **infectieuses**.\n\n### Prise en charge\n- **Hospitalisation en urgence**.\n- **Examens biologiques** pour évaluer la gravité ; **rééquilibration hydro-électrolytique** ; traitement des **défaillances viscérales** ; **recherche et traitement de la cause**.\n- **Traitement symptomatique** : **réchauffement** du malade (limite les pertes caloriques, l'hypercatabolisme, la dénutrition) ; dans les **formes graves**, **corticothérapie locale de niveau 1** (très forte) = amélioration rapide.","keyPoints":["Complications : **hydro-électrolytiques**, **décubitus** (escarres, dénutrition), **infectieuses**, **décès** (jusqu'à **20 %**).","**Hospitalisation en urgence** : examens biologiques, **rééquilibration hydro-électrolytique**, défaillances viscérales, **cause**.","**Réchauffement** ; formes graves : **corticothérapie locale de niveau 1** (très forte)."],"pitfalls":["Ne pas attendre la cause pour traiter : **réhydratation, réchauffement** et recherche **étiologique** se mènent **ensemble**.","La mortalité vient surtout des **complications infectieuses**."],"src":"p. 92-93"}],"essentials":[{"id":"d114-ess-01","rank":"A","text":"Définition d'un exanthème : **érythème d'apparition brutale et transitoire** (± énanthème), bénin ou potentiellement grave.","src":"p. 84","q":"Comment définit-on un exanthème (mode d'apparition, composante muqueuse, gravité) ?"},{"id":"d114-ess-02","rank":"A","text":"Causes d'exanthème selon l'âge : **virales** chez l'enfant ; **VIH, syphilis et médicaments** chez l'adulte.","src":"p. 84, 90","q":"Quelles sont les causes d'exanthème selon l'âge (enfant, adulte) ?"},{"id":"d114-ess-03","rank":"A","text":"Trois types sémiologiques d'exanthème : **roséoliforme** (petites macules rosées séparées), **morbilliforme** (peau saine entre les plaques), **scarlatiniforme** (rouge vif, sans peau saine, plis).","src":"p. 85","q":"Pouvez-vous citer les 3 types sémiologiques d'exanthème et leur description ?"},{"id":"d114-ess-04","rank":"A","text":"Orientation étiologique d'un exanthème : **viral** = fièvre, syndrome grippal, énanthème, adénopathies ; **médicamenteux** = prurit, éruption polymorphe, hyperéosinophilie.","src":"p. 85","q":"Quels éléments orientent vers une cause virale ou médicamenteuse devant un exanthème ?"},{"id":"d114-ess-05","rank":"B","text":"Examens d'un exanthème de l'enfant : **aucun** sauf suspicion de **scarlatine** (numération-formule sanguine ou NFS, gorge) ou de **Kawasaki** (NFS, plaquettes, échographie cardiaque).","src":"p. 85","q":"Quels examens demander devant un exanthème de l'enfant, et dans quels cas ?"},{"id":"d114-ess-06","rank":"A","text":"Exanthème subit, tableau clinique typique : **nourrisson de 6 à 18 mois**, **HHV6**, **fièvre isolée 3 jours** puis éruption roséoliforme du tronc ; **pas d'éviction**.","src":"p. 85, 90","q":"Comment décrire le tableau typique de l'exanthème subit (âge, virus, évolution, éviction) ?"},{"id":"d114-ess-07","rank":"A","text":"Rubéole et grossesse : chez la femme enceinte **non immunisée**, risque de **mort fœtale** ou de **malformations** graves.","src":"p. 85, 90","q":"Quel est le risque de la rubéole chez la femme enceinte non immunisée ?"},{"id":"d114-ess-08","rank":"A","text":"Rougeole, comment l'évoquer en pratique ? **Catarrhe oculo-nasal + conjonctivite + exanthème fébrile** ; **signe de Köplick** ; exanthème débutant derrière les oreilles.","src":"p. 86, 90","q":"Quels éléments cliniques permettent d'évoquer une rougeole ?"},{"id":"d114-ess-09","rank":"A","text":"Complications de la rougeole : **pneumopathie**, **encéphalite** (grave), **kératite** (cécité).","src":"p. 86","q":"Pouvez-vous citer les 3 complications de la rougeole ?"},{"id":"d114-ess-10","rank":"A","text":"Conduite à tenir devant une rougeole : **déclaration obligatoire** ; **éviction de la collectivité jusqu'à 5 jours après le début de l'éruption**.","src":"p. 86","q":"Quelle est la conduite à tenir devant une rougeole (déclaration, éviction) ?"},{"id":"d114-ess-11","rank":"A","text":"Mégalérythème épidémique, tableau clinique typique : **parvovirus B19**, **enfant de 5 à 10 ans**, **joues œdémateuses**, tronc à bords émiettés, puis érythème en **gants et chaussettes**.","src":"p. 86-87","q":"Comment décrire le tableau typique du mégalérythème épidémique (virus, âge, séquence des signes) ?"},{"id":"d114-ess-12","rank":"A","text":"Parvovirus B19 chez la femme enceinte : risque d'**anasarque fœtale** ; **pas de risque tératogène**.","src":"p. 86, 90","q":"Quel est le risque du parvovirus B19 chez la femme enceinte ?"},{"id":"d114-ess-13","rank":"A","text":"Mononucléose infectieuse, tableau clinique typique : virus d'Epstein-Barr (**EBV**), **adolescent**, fièvre, asthénie, polyadénopathie, splénomégalie ; **lymphocytes hyperbasophiles**.","src":"p. 86","q":"Comment décrire le tableau typique de la mononucléose infectieuse (virus, terrain, signes cliniques et biologiques) ?"},{"id":"d114-ess-14","rank":"A","text":"Rash à l'ampicilline : au cours de la mononucléose, exanthème **inconstant (5-10 %)** sauf sous **pénicilline A** ; **à ne pas confondre avec une toxidermie**.","src":"p. 82, 86","q":"Qu'est-ce que le rash à l'ampicilline et dans quel contexte survient-il ?"},{"id":"d114-ess-15","rank":"A","text":"Scarlatine, tableau clinique typique : **streptocoque A**, enfant de 5 à 10 ans, début brutal avec **angine**, éruption des **grands plis**, **langue framboisée**.","src":"p. 88","q":"Comment décrire le tableau typique de la scarlatine (agent, âge, début, éruption, langue) ?"},{"id":"d114-ess-16","rank":"A","text":"Prise en charge d'une scarlatine : **prélèvement de gorge**, **amoxicilline**, **éviction scolaire jusqu'à 48 h** après le début du traitement.","src":"p. 88","q":"Quelle est la prise en charge d'une scarlatine (prélèvement, traitement, éviction) ?"},{"id":"d114-ess-17","rank":"A","text":"Complications post-streptococciques de la scarlatine : **glomérulonéphrite** et **rhumatisme articulaire aigu**.","src":"p. 88","q":"Quelles sont les complications post-streptococciques de la scarlatine ?"},{"id":"d114-ess-18","rank":"A","text":"Scarlatine staphylococcique, tableau clinique : **pas d'angine**, grands plis et zones péri-orificielles puis **décollement bulleux** ; traitement par **oxacilline**.","src":"p. 88","q":"Comment décrire le tableau de la scarlatine staphylococcique et son traitement ?"},{"id":"d114-ess-19","rank":"B","text":"Exanthème scarlatiniforme diffus, fébrile, d'apparition brutale : rechercher un **choc toxique staphylococcique** et des signes de retentissement hémodynamique.","src":"p. 90","q":"Devant un exanthème scarlatiniforme diffus, fébrile, d'apparition brutale, que doit-on rechercher ?"},{"id":"d114-ess-20","rank":"A","text":"Syndrome de Kawasaki, diagnostic : vasculite de l'**enfant < 5 ans**, **fièvre > 38,5 °C pendant plus de 5 jours**, **au moins 5 critères sur 6**.","src":"p. 88","q":"Quels sont les critères diagnostiques du syndrome de Kawasaki (terrain, fièvre, nombre de critères) ?"},{"id":"d114-ess-21","rank":"A","text":"Risque et prise en charge du Kawasaki : **anévrismes coronariens** (retard thérapeutique) ; **hospitalisation indispensable**.","src":"p. 88, 90","q":"Quel est le risque du syndrome de Kawasaki et quelle prise en charge ?"},{"id":"d114-ess-22","rank":"A","text":"Définition de l'érythrodermie, critères : **érythème + desquamation** sur **plus de 90 %** de la surface corporelle, **depuis au moins 6 semaines** ; ≠ exanthème.","src":"p. 90, 93","q":"Quels sont les critères de définition d'une érythrodermie (érythème, étendue, durée) et la différence avec l'exanthème ?"},{"id":"d114-ess-23","rank":"A","text":"Signes cliniques d'une érythrodermie : **prurit constant**, **dysrégulation thermique**, pachydermie, œdème du visage, polyadénopathie ; urgence, **hospitalisation**.","src":"p. 90-91","q":"Quels sont les signes cliniques d'une érythrodermie et la conduite à tenir ?"},{"id":"d114-ess-24","rank":"A","text":"Quelles sont les causes principales d'érythrodermie ? **Psoriasis**, **dermatite atopique**, **toxidermie (DRESS)**, **syndrome de Sézary** ; aussi VIH, gale croûteuse.","src":"p. 91, 93","q":"Quelles sont les causes principales d'érythrodermie ?"},{"id":"d114-ess-25","rank":"A","text":"Érythrodermie, prise en charge : **hospitalisation en urgence**, **rééquilibration hydro-électrolytique**, **réchauffement**, recherche de la cause ; mortalité **jusqu'à 20 %**.","src":"p. 93","q":"Quelle est la prise en charge d'une érythrodermie (lieu, mesures, mortalité) ?"}],"numbers":[{"id":"d114-num-01","rank":"A","label":"Érythrodermie : surface corporelle atteinte","value":"plus de 90 %","src":"p. 90"},{"id":"d114-num-02","rank":"A","label":"Érythrodermie : durée d'évolution","value":"depuis au moins 6 semaines","src":"p. 90, 93"},{"id":"d114-num-03","rank":"A","label":"Mortalité de l'érythrodermie","value":"jusqu'à 20 % (complications, surtout infectieuses)","src":"p. 93"},{"id":"d114-num-04","rank":"B","label":"Exanthème subit : âge de survenue","value":"nourrisson de 6 à 18 mois","src":"p. 85"},{"id":"d114-num-05","rank":"A","label":"Exanthème subit : durée de la fièvre isolée avant l'éruption","value":"48-72 heures (3 jours), 39-40 °C","src":"p. 85, 90"},{"id":"d114-num-06","rank":"B","label":"Rubéole : âge de survenue","value":"15 à 25 ans","src":"p. 85"},{"id":"d114-num-07","rank":"B","label":"Rubéole : incubation et contagiosité","value":"incubation 3 semaines ; contagieuse 7 jours avant et 14 jours après le début de l'éruption","src":"p. 85"},{"id":"d114-num-08","rank":"A","label":"Rougeole : incubation","value":"10-12 jours","src":"p. 86"},{"id":"d114-num-09","rank":"A","label":"Rougeole : contagiosité","value":"3-5 jours avant et 4 jours après l'éruption","src":"p. 86"},{"id":"d114-num-10","rank":"A","label":"Rougeole : éviction de la collectivité","value":"jusqu'à 5 jours après le début de l'éruption","src":"p. 86"},{"id":"d114-num-11","rank":"B","label":"Mégalérythème épidémique : âge de l'enfant","value":"5 à 10 ans","src":"p. 86"},{"id":"d114-num-12","rank":"A","label":"Mononucléose infectieuse : fréquence de l'exanthème (hors pénicilline A)","value":"inconstant : 5-10 %","src":"p. 86"},{"id":"d114-num-13","rank":"A","label":"Mononucléose infectieuse : incubation et contagiosité","value":"incubation 4 à 6 semaines ; contagiosité maximale en phase aiguë (jusqu'à 6 mois)","src":"p. 86"},{"id":"d114-num-14","rank":"A","label":"Scarlatine : âge, incubation et contagiosité","value":"enfant de 5 à 10 ans ; incubation 2 à 4 jours ; contagiosité 2 à 3 semaines","src":"p. 88"},{"id":"d114-num-15","rank":"A","label":"Scarlatine : éviction scolaire","value":"jusqu'à 48 heures après le début du traitement","src":"p. 88"},{"id":"d114-num-16","rank":"B","label":"Kawasaki : âge de l'enfant","value":"moins de 5 ans","src":"p. 88"},{"id":"d114-num-17","rank":"A","label":"Kawasaki : fièvre","value":"> 38,5 °C pendant plus de 5 jours (avec altération de l'état général)","src":"p. 88"},{"id":"d114-num-18","rank":"A","label":"Kawasaki : seuil diagnostique","value":"au moins 5 critères sur 6","src":"p. 88"},{"id":"d114-num-19","rank":"B","label":"Érythrodermie idiopathique : fréquence","value":"10 à 15 % des cas","src":"p. 91"}],"mnemonics":[{"id":"d114-mn-01","rank":"A","title":"Les 3 types d'exanthème : l'aspect à retenir","mnemonic":"ROSÉ séparé · MORBI intervalles · SCARLATI sans intervalle","expansion":"- **Roséoliforme** : petites macules **rosées**, pâles, **bien séparées**\n- **Morbilliforme** : maculo-papules rouges, plaques séparées par des **intervalles de peau saine**\n- **Scarlatiniforme** : plaques rouge vif, **sans intervalle de peau saine**, plus marquées dans les plis","src":"p. 85"},{"id":"d114-mn-02","rank":"B","title":"Causes principales de chaque type d'exanthème","mnemonic":"SRVS · RMM · SK","expansion":"- **S·R·V·S** (roséoliforme) : **S**ubit (exanthème subit), **R**ubéole, **V**IH (primo-infection), **S**yphilis secondaire\n- **R·M·M** (morbilliforme) : **R**ougeole, **M**égalérythème épidémique, **M**ononucléose infectieuse\n- **S·K** (scarlatiniforme) : **S**carlatine, syndrome de **K**awasaki","src":"p. 85-86, 88"},{"id":"d114-mn-03","rank":"A","title":"Les 6 critères du Kawasaki (5 sur 6)","mnemonic":"FÉE-CLE","expansion":"- **F**ièvre > 38,5 °C pendant plus de 5 jours\n- **É**nanthème : chéilite et langue framboisée\n- **E**xtrémités : érythème et œdème\n- **C**onjonctivite bilatérale (œdème des paupières)\n- **L**ymphadénite, souvent asymétrique\n- **E**xanthème polymorphe\n\nDiagnostic si **au moins 5 critères sur 6**.","src":"p. 88"},{"id":"d114-mn-04","rank":"A","title":"Les 4 causes principales d'érythrodermie","mnemonic":"PADS","expansion":"- **P**soriasis\n- **A**topie : dermatite atopique (eczéma)\n- **D**RESS : toxidermie\n- **S**ézary : lymphome cutané\n\nAussi : VIH, gale croûteuse.","src":"p. 91, 93"},{"id":"d114-mn-05","rank":"A","title":"Éviction de la collectivité","mnemonic":"Rougeole 5 j · Scarlatine 48 h · Subit 0","expansion":"- **Rougeole** : jusqu'à **5 jours** après le début de l'éruption\n- **Scarlatine** : jusqu'à **48 heures** après le début du traitement\n- **Exanthème subit** : **aucune** éviction recommandée","src":"p. 85-86, 88"},{"id":"d114-mn-06","rank":"B","title":"Sérologies de la femme enceinte devant un exanthème","mnemonic":"T-R-C-P-S","expansion":"- **T**oxoplasmose\n- **R**ubéole\n- **C**MV (cytomégalovirus)\n- **P**arvovirus B19\n- **S**yphilis","src":"p. 85"}]},"questions":[{"id":"d114-qroc-001","type":"QROC","rank":"A","objective":"d114-obj-01","tags":["définition"],"difficulty":1,"question":"Comment définit-on un exanthème ?","answer":"Un érythème d'apparition brutale et transitoire","accept":["érythème brutal et transitoire","érythème d'apparition brutale et transitoire"],"keywords":["érythème","brutal","transitoire"],"explanation":"Un exanthème est un érythème d'apparition brutale et transitoire, isolé ou associé à une symptomatologie variée ; il peut s'accompagner d'une atteinte muqueuse (énanthème), être bénin ou potentiellement grave. Ses deux causes principales sont infectieuses et médicamenteuses.","src":"p. 84"},{"id":"d114-qroc-002","type":"QROC","rank":"A","objective":"d114-obj-10","tags":["étiologie"],"difficulty":1,"question":"Quelles infections sexuellement transmissibles faut-il évoquer devant un exanthème de l'adulte ?","answer":"La syphilis et le VIH","accept":["syphilis et vih","vih et syphilis","vih, syphilis"],"keywords":["syphilis","vih"],"explanation":"Chez l'adulte, les causes à évoquer sont infectieuses (IST : syphilis, VIH) et médicamenteuses (toxidermie) ; chez l'enfant, la cause est le plus souvent virale.","src":"p. 84, 90"},{"id":"d114-qroc-003","type":"QROC","rank":"A","objective":"d114-obj-03","tags":["clinique"],"difficulty":1,"question":"Quels sont les trois types séméiologiques d'exanthème ?","answer":"Roséoliforme, morbilliforme et scarlatiniforme","accept":["roséoliforme, morbilliforme, scarlatiniforme","rubéoliforme, morbilliforme, scarlatiniforme"],"keywords":["roséol","morbill","scarlat"],"explanation":"On distingue les exanthèmes roséoliformes (ou rubéoliformes), morbilliformes et scarlatiniformes selon l'aspect de l'éruption.","src":"p. 85"},{"id":"d114-qroc-004","type":"QROC","rank":"A","objective":"d114-obj-23","tags":["clinique"],"difficulty":1,"question":"Quel est l'aspect d'un exanthème roséoliforme ?","answer":"De petites macules rosées, pâles, bien séparées","accept":["petites macules rosées","macules rosées pâles bien séparées","petites macules rosées pâles"],"keywords":["macule","rosé"],"explanation":"L'exanthème roséoliforme (ou rubéoliforme) est fait de petites macules rosées, pâles, bien séparées les unes des autres.","src":"p. 85"},{"id":"d114-qroc-005","type":"QROC","rank":"A","objective":"d114-obj-19","tags":["clinique"],"difficulty":1,"question":"Comment se présente un exanthème morbilliforme ?","answer":"Maculo-papuleux rouge, confluant en plaques séparées de peau saine","accept":["maculo-papuleux rouges","maculo-papuleux","macules et papules rouges confluentes"],"keywords":["maculo","papul"],"explanation":"L'exanthème morbilliforme est maculo-papuleux, rouge ; les éléments peuvent confluer en plaques séparées par des espaces de peau saine.","src":"p. 85"},{"id":"d114-qroc-006","type":"QROC","rank":"A","objective":"d114-obj-20","tags":["clinique","diagnostic"],"difficulty":2,"question":"Quel caractère distingue un exanthème scarlatiniforme d'un exanthème morbilliforme quant à la peau entre les plaques ?","answer":"Aucun intervalle de peau saine (plaques diffuses rouge vif)","accept":["sans intervalle de peau saine","pas de peau saine","absence de peau saine","pas d'intervalle de peau saine","aucun intervalle de peau saine"],"keywords":[],"explanation":"Dans l'exanthème scarlatiniforme, les plaques diffuses rouge vif, légèrement granitées, chaudes ou cuisantes, s'intensifiant dans les plis, ne laissent aucun intervalle de peau saine ; elles peuvent évoluer vers une desquamation en larges lambeaux.","src":"p. 85"},{"id":"d114-qroc-007","type":"QROC","rank":"A","objective":"d114-obj-03","tags":["diagnostic","étiologie"],"difficulty":2,"question":"Citez les trois signes en faveur d'une origine médicamenteuse d'un exanthème.","answer":"Prurit, éruption polymorphe, hyperéosinophilie sanguine","accept":["prurit, polymorphisme, hyperéosinophilie","prurit, polymorphe, hyperéosinophilie"],"keywords":["prurit","polymorph","éosinophil"],"explanation":"Une origine virale s'oriente plutôt avec fièvre, syndrome grippal, énanthème et poly-adénopathie ; une origine médicamenteuse avec prurit, caractère polymorphe de l'éruption et hyperéosinophilie sanguine.","src":"p. 85"},{"id":"d114-qroc-008","type":"QROC","rank":"A","objective":"d114-obj-16","tags":["diagnostic","clinique"],"difficulty":1,"question":"Quels trois éléments associés font évoquer une rougeole ?","answer":"Catarrhe oculo-nasal, conjonctivite et exanthème fébrile","accept":["catarrhe oculo-nasal, conjonctivite, exanthème fébrile","catarrhe oculo-nasal, conjonctivite et exanthème"],"keywords":["catarrhe","conjonctivite","exanthème"],"explanation":"Il faut savoir évoquer une rougeole devant l'association catarrhe oculo-nasal, conjonctivite et exanthème fébrile.","src":"p. 90"},{"id":"d114-qroc-009","type":"QROC","rank":"A","objective":"d114-obj-26","tags":["clinique"],"difficulty":1,"question":"Comment s'appelle le semis de papules de la face interne des joues observé dans la phase pré-éruptive de la rougeole ?","answer":"Le signe de Köplick","accept":["signe de köplick","köplick","koplick"],"keywords":["koplick"],"explanation":"La phase pré-éruptive associe fièvre élevée (39-40 °C), catarrhe oculo-nasal, conjonctivite et signe de Köplick ; l'exanthème débute ensuite en région rétro-auriculaire et s'étend à tout le corps en une seule poussée.","src":"p. 86"},{"id":"d114-qroc-010","type":"QROC","rank":"A","objective":"d114-obj-26","tags":["complications"],"difficulty":2,"question":"Quelle complication neurologique grave peut compliquer la rougeole ?","answer":"Une encéphalite","accept":["encéphalite","une encéphalite"],"keywords":["encéphal"],"explanation":"La rougeole peut se compliquer d'une pneumopathie, d'une encéphalite (grave) et d'une kératite avec risque de cécité. C'est une maladie à déclaration obligatoire, avec éviction de la collectivité jusqu'à 5 jours après le début de l'éruption.","src":"p. 86"},{"id":"d114-qroc-011","type":"QROC","rank":"A","objective":"d114-obj-29","tags":["étiologie","pédiatrie"],"difficulty":1,"question":"Quel virus est responsable de l'exanthème subit (roséole infantile) ?","answer":"Le virus HHV6 (herpèsvirus humain 6)","accept":["hhv6","hhv 6","herpèsvirus humain 6","human herpesvirus 6"],"keywords":[],"explanation":"L'exanthème subit est une primo-infection par HHV6 ; aucune éviction de la collectivité n'est recommandée.","src":"p. 85"},{"id":"d114-qroc-012","type":"QROC","rank":"A","objective":"d114-obj-25","tags":["diagnostic","pédiatrie"],"difficulty":2,"question":"Chez un nourrisson, quel diagnostic évoque une éruption roséoliforme apparue après 3 jours de fièvre isolée ?","answer":"L'exanthème subit (roséole infantile)","accept":["exanthème subit","roséole infantile","roséole"],"keywords":[],"explanation":"L'exanthème subit associe une fièvre à 39-40 °C isolée pendant 48 à 72 heures, puis un exanthème prédominant sur le tronc, en une seule poussée ; les complications sont rares (convulsions fébriles).","src":"p. 85, 90"},{"id":"d114-qroc-013","type":"QROC","rank":"A","objective":"d114-obj-27","tags":["grossesse","complications"],"difficulty":1,"question":"Quel risque fait redouter la rubéole chez une femme enceinte non immunisée ?","answer":"Mort fœtale ou malformations fœtales graves","accept":["malformations fœtales","malformations","mort fœtale"],"keywords":["malformation"],"explanation":"La rubéole chez la femme enceinte non immunisée expose à une mort fœtale ou à des malformations (neurologiques, sensorielles) ; en cas de rubéole en collectivité, on informe le personnel, les parents et la femme enceinte.","src":"p. 85, 90"},{"id":"d114-qroc-014","type":"QROC","rank":"A","objective":"d114-obj-28","tags":["étiologie","pédiatrie"],"difficulty":1,"question":"Quel virus est responsable du mégalérythème épidémique ?","answer":"Le parvovirus B19","accept":["parvovirus b19","parvovirus","b19"],"keywords":["parvovirus"],"explanation":"Le mégalérythème épidémique est dû au parvovirus B19 ; la contagiosité est limitée à la phase pré-éruptive.","src":"p. 86"},{"id":"d114-qroc-015","type":"QROC","rank":"A","objective":"d114-obj-28","tags":["clinique"],"difficulty":2,"question":"Quel aspect prend l'éruption des extrémités dans le mégalérythème épidémique ?","answer":"Un érythème en « gants et chaussettes »","accept":["gants et chaussettes","gants chaussettes"],"keywords":["gant","chaussette"],"explanation":"L'éruption débute par une atteinte érythémateuse avec œdème des joues, puis un érythème du tronc à bords émiettés ; l'érythème en gants et chaussettes complète le tableau.","src":"p. 86-87"},{"id":"d114-qroc-016","type":"QROC","rank":"A","objective":"d114-obj-28","tags":["grossesse","complications"],"difficulty":1,"question":"Quel risque fœtal expose la primo-infection à parvovirus B19 pendant la grossesse ?","answer":"Une anasarque fœtale","accept":["anasarque fœtale","anasarque"],"keywords":["anasarque"],"explanation":"Il n'y a pas de risque tératogène ; en cas d'infection au 2e trimestre, le risque est l'anasarque fœtale, la myocardite et l'anémie fœtale.","src":"p. 86, 90"},{"id":"d114-qroc-017","type":"QROC","rank":"A","objective":"d114-obj-30","tags":["étiologie"],"difficulty":1,"question":"Quel virus est responsable de la mononucléose infectieuse ?","answer":"Le virus d'Epstein-Barr (EBV)","accept":["ebv","epstein-barr","virus d'epstein-barr"],"keywords":["epstein"],"explanation":"La mononucléose infectieuse touche l'adolescent : fièvre et asthénie importantes, poly-adénopathie, splénomégalie, exanthème inconstant.","src":"p. 86"},{"id":"d114-qroc-018","type":"QROC","rank":"A","objective":"d114-obj-30","tags":["biologie","diagnostic"],"difficulty":2,"question":"Quelle anomalie de la NFS caractérise la mononucléose infectieuse ?","answer":"Une lymphocytose avec lymphocytes hyperbasophiles","accept":["lymphocytes hyperbasophiles","lymphocytose hyperbasophile","hyperbasophiles"],"keywords":["lymphocyt","hyperbasophil"],"explanation":"Lymphocytose élevée avec lymphocytes hyperbasophiles ; les complications rares sont l'hépatite, la méningo-encéphalite, la rupture splénique et l'agranulocytose.","src":"p. 86"},{"id":"d114-qroc-019","type":"QROC","rank":"A","objective":"d114-obj-31","tags":["étiologie"],"difficulty":1,"question":"Quel germe est responsable de la scarlatine ?","answer":"Le streptocoque du groupe A","accept":["streptocoque du groupe a","streptocoque a"],"keywords":["streptocoque"],"explanation":"Streptocoque du groupe A sécréteur d'exotoxines ; début brutal avec fièvre, douleurs pharyngées, angine rouge et adénopathies sous-maxillaires, puis éruption des grands plis et langue framboisée.","src":"p. 88"},{"id":"d114-qroc-020","type":"QROC","rank":"A","objective":"d114-obj-31","tags":["traitement"],"difficulty":1,"question":"Quel antibiotique est prescrit dans la scarlatine ?","answer":"L'amoxicilline","accept":["amoxicilline","l'amoxicilline"],"keywords":["amoxicilline"],"explanation":"Traitement antibiotique par amoxicilline, après prélèvement de gorge ; l'éviction scolaire dure jusqu'à 48 heures après le début du traitement.","src":"p. 88"},{"id":"d114-qroc-021","type":"QROC","rank":"A","objective":"d114-obj-31","tags":["complications"],"difficulty":2,"question":"Quelles complications post-streptococciques peuvent suivre une scarlatine ?","answer":"Glomérulonéphrites et rhumatisme articulaire aigu","accept":["glomérulonéphrite et rhumatisme articulaire aigu","glomérulonéphrites, rhumatisme articulaire aigu"],"keywords":["glomérulo","rhumatisme"],"explanation":"Les complications post-streptococciques de la scarlatine sont les glomérulonéphrites et le rhumatisme articulaire aigu.","src":"p. 88"},{"id":"d114-qroc-022","type":"QROC","rank":"A","objective":"d114-obj-07","tags":["traitement","pédiatrie"],"difficulty":2,"question":"Quel antibiotique traite la scarlatine staphylococcique (épidermolyse staphylococcique) ?","answer":"L'oxacilline","accept":["oxacilline","l'oxacilline"],"keywords":["oxacilline"],"explanation":"Elle est due à Staphylococcus aureus sécréteur d'entérotoxines ou de TSST1 : absence d'angine, exanthème débutant aux grands plis et aux régions péri-orificielles puis décollement bulleux ; traitement par oxacilline.","src":"p. 88"},{"id":"d114-qroc-023","type":"QROC","rank":"A","objective":"d114-obj-32","tags":["définition","pédiatrie"],"difficulty":1,"question":"Quelle est la nature du syndrome de Kawasaki ?","answer":"Une vasculite systémique aiguë","accept":["vasculite systémique aiguë","vasculite systémique","vasculite"],"keywords":["vasculite"],"explanation":"Le syndrome de Kawasaki (adéno-cutanéo-muqueux) est une vasculite systémique aiguë de l'enfant de moins de 5 ans.","src":"p. 88"},{"id":"d114-qroc-024","type":"QROC","rank":"A","objective":"d114-obj-08","tags":["diagnostic","clinique"],"difficulty":2,"question":"Quelle fièvre est exigée parmi les critères du syndrome de Kawasaki ?","answer":"Fièvre > 38,5 °C pendant plus de 5 jours","accept":["plus de 5 jours","38,5 plus de 5 jours","supérieure à 38,5 pendant plus de 5 jours"],"keywords":["38,5","5 jours"],"explanation":"Fièvre élevée > 38,5 °C plus de 5 jours avec altération de l'état général, conjonctivite bilatérale avec œdème des paupières, chéilite et langue framboisée, érythème et œdème des extrémités, exanthème polymorphe, lymphadénite souvent asymétrique.","src":"p. 88"},{"id":"d114-qroc-025","type":"QROC","rank":"A","objective":"d114-obj-32","tags":["diagnostic"],"difficulty":2,"question":"Combien de critères diagnostiques sur six faut-il réunir pour poser le diagnostic de syndrome de Kawasaki ?","answer":"Au moins 5 sur 6","accept":["5 sur 6","au moins 5","cinq sur six","au moins cinq","5 critères sur 6"],"keywords":["5"],"explanation":"Le diagnostic de Kawasaki est retenu si au moins cinq des six critères diagnostiques sont présents.","src":"p. 88"},{"id":"d114-qroc-026","type":"QROC","rank":"A","objective":"d114-obj-32","tags":["complications"],"difficulty":1,"question":"Quelle complication cardiaque redoute-t-on dans la maladie de Kawasaki en cas de retard thérapeutique ?","answer":"Des anévrismes coronariens","accept":["anévrismes coronariens","anévrisme coronarien","anévrismes coronaires"],"keywords":["anévr"],"explanation":"Les complications cardiaques sont les anévrismes coronariens et les troubles du rythme ; des décès par myocardite ou infarctus sont possibles.","src":"p. 88, 90"},{"id":"d114-qroc-027","type":"QROC","rank":"A","objective":"d114-obj-24","tags":["urgence","pédiatrie"],"difficulty":1,"question":"Quelle orientation est indispensable pour un enfant atteint de syndrome de Kawasaki ?","answer":"Une hospitalisation","accept":["hospitalisation","une hospitalisation"],"keywords":["hospitalis"],"explanation":"L'hospitalisation est indispensable, en raison du risque cardiaque ; la biologie montre un syndrome inflammatoire (CRP élevée, hyperleucocytose à PNN, thrombocytose).","src":"p. 88"},{"id":"d114-qroc-028","type":"QROC","rank":"A","objective":"d114-obj-02","tags":["définition"],"difficulty":1,"question":"Quelle surface corporelle minimale est touchée dans une érythrodermie ?","answer":"Plus de 90 %","accept":["90 %","plus de 90 %","90"],"keywords":["90"],"explanation":"L'érythrodermie associe un érythème confluant et une desquamation touchant l'ensemble des téguments (plus de 90 % de la surface corporelle), évoluant depuis au moins 6 semaines.","src":"p. 90"},{"id":"d114-qroc-029","type":"QROC","rank":"A","objective":"d114-obj-02","tags":["définition"],"difficulty":1,"question":"Depuis combien de temps minimum l'érythème doit-il évoluer pour parler d'érythrodermie ?","answer":"Au moins 6 semaines","accept":["6 semaines","6 semaines minimum","au moins 6 semaines"],"keywords":["6"],"explanation":"Un exanthème ou une nécrolyse épidermique avec décollement d'évolution aiguë ne sont pas des érythrodermies ; érythrodermie n'est pas synonyme d'érythème ou d'exanthème.","src":"p. 90-91, 93"},{"id":"d114-qroc-030","type":"QROC","rank":"A","objective":"d114-obj-21","tags":["clinique"],"difficulty":2,"question":"Comment est l'érythème d'une érythrodermie aux zones déclives ?","answer":"Plus violacé","accept":["plus violacé","violacé"],"keywords":["violac"],"explanation":"L'érythème est généralisé, inflammatoire, plus violacé aux zones déclives, d'intensité variable d'un jour à l'autre ; la desquamation est constante, fine ou en larges lambeaux.","src":"p. 90"},{"id":"d114-qroc-031","type":"QROC","rank":"A","objective":"d114-obj-09","tags":["urgence","traitement"],"difficulty":1,"question":"Quelle prise en charge nécessite une érythrodermie ?","answer":"Une hospitalisation en urgence (service spécialisé)","accept":["hospitalisation en urgence","hospitalisation urgente","hospitalisation"],"keywords":["hospitalis"],"explanation":"C'est une urgence dermatologique : hospitalisation avec examens biologiques de gravité, rééquilibration hydro-électrolytique, traitement des défaillances viscérales et recherche étiologique.","src":"p. 90, 93"},{"id":"d114-qroc-032","type":"QROC","rank":"A","objective":"d114-obj-09","tags":["diagnostic","traitement"],"difficulty":2,"question":"Quelles sont les trois étapes de la prise en charge d'une érythrodermie ?","answer":"Reconnaître, chercher l'étiologie, apprécier la gravité","accept":["reconnaître l'érythrodermie, rechercher l'étiologie, apprécier la gravité","reconnaître, rechercher l'étiologie, apprécier la gravité"],"keywords":["reconna","étiolog","gravité"],"explanation":"Les trois étapes sont : reconnaître l'érythrodermie, rechercher l'étiologie en vue d'un éventuel traitement spécifique, apprécier la gravité immédiate et proposer une attitude symptomatique.","src":"p. 90"},{"id":"d114-qroc-033","type":"QROC","rank":"A","objective":"d114-obj-17","tags":["étiologie"],"difficulty":1,"question":"Quel lymphome T cutané épidermotrope peut se présenter sous la forme d'une érythrodermie ?","answer":"Le syndrome de Sézary","accept":["syndrome de sézary","sézary"],"keywords":["sézary"],"explanation":"Le syndrome de Sézary, lymphome T cutané épidermotrope, est une cause d'érythrodermie de l'adulte ; la biopsie cutanée doit être répétée en cas de suspicion de lymphome cutané.","src":"p. 91-92"},{"id":"d114-qroc-034","type":"QROC","rank":"A","objective":"d114-obj-17","tags":["étiologie"],"difficulty":1,"question":"Quelle toxidermie est une cause d'érythrodermie ?","answer":"Le DRESS","accept":["dress","le dress"],"keywords":["dress"],"explanation":"DRESS : Drug Rash with hyper-Eosinophilia and Systemic Symptoms. Les principales causes d'érythrodermie sont le psoriasis, la dermatite atopique, le lymphome cutané et la toxidermie (DRESS).","src":"p. 91, 93"},{"id":"d114-qroc-035","type":"QROC","rank":"A","objective":"d114-obj-06","tags":["complications"],"difficulty":1,"question":"Quelle mortalité peut atteindre l'érythrodermie ?","answer":"Jusqu'à 20 %","accept":["20 %","20","jusqu'à 20 %"],"keywords":["20"],"explanation":"La mortalité, liée aux complications et notamment infectieuses, peut atteindre 20 % ; les complications sont hydro-électrolytiques, de décubitus et infectieuses.","src":"p. 93"},{"id":"d114-qroc-036","type":"QROC","rank":"B","objective":"d114-obj-05","tags":["diagnostic","pièges"],"difficulty":2,"question":"Quelle éruption survient chez un patient atteint de mononucléose infectieuse traité par pénicilline A, et ne doit pas être confondue avec une toxidermie ?","answer":"Un exanthème : le rash à l'ampicilline","accept":["rash à l'ampicilline","rash ampicilline","rash aux pénicillines a","exanthème à l'ampicilline"],"keywords":[],"explanation":"L'exanthème de la mononucléose est inconstant (5-10 %), sauf en cas de prescription de pénicilline A : c'est le rash à l'ampicilline, complication classique à ne pas confondre avec une toxidermie aux pénicillines.","src":"p. 82, 86"},{"id":"d114-qroc-037","type":"QROC","rank":"B","objective":"d114-obj-04","tags":["épidémiologie","pédiatrie"],"difficulty":1,"question":"Quel est le terrain classique du mégalérythème épidémique ?","answer":"L'enfant de 5 à 10 ans","accept":["enfant de 5 à 10 ans","5 à 10 ans","5-10 ans"],"keywords":["5","10"],"explanation":"Le mégalérythème épidémique (parvovirus B19) touche classiquement l'enfant de 5 à 10 ans.","src":"p. 86"},{"id":"d114-qroc-038","type":"QROC","rank":"B","objective":"d114-obj-29","tags":["épidémiologie","pédiatrie"],"difficulty":1,"question":"Quel est l'âge de survenue de l'exanthème subit ?","answer":"Nourrisson de 6 à 18 mois","accept":["6 à 18 mois","6-18 mois"],"keywords":["6","18"],"explanation":"L'exanthème subit survient chez le nourrisson de 6 à 18 mois, après une fièvre à 39-40 °C isolée pendant 48 à 72 heures.","src":"p. 85"},{"id":"d114-qroc-039","type":"QROC","rank":"B","objective":"d114-obj-32","tags":["épidémiologie","pédiatrie"],"difficulty":1,"question":"Quel est le terrain habituel du syndrome de Kawasaki ?","answer":"L'enfant de moins de 5 ans","accept":["moins de 5 ans","enfant de moins de 5 ans"],"keywords":["5"],"explanation":"Le syndrome de Kawasaki est une vasculite systémique aiguë de l'enfant de moins de 5 ans.","src":"p. 88"},{"id":"d114-qroc-040","type":"QROC","rank":"B","objective":"d114-obj-25","tags":["paraclinique","pédiatrie"],"difficulty":2,"question":"Chez l'enfant, quel examen complémentaire est indispensable devant un exanthème ?","answer":"Aucun (sauf suspicion de scarlatine ou de Kawasaki)","accept":["aucun","aucun examen","aucun examen n'est indispensable"],"keywords":["aucun"],"explanation":"Chez l'enfant, aucun examen n'est indispensable, sauf si l'on suspecte une scarlatine (NFS, prélèvement de gorge) ou un syndrome de Kawasaki (NFS, plaquettes, échographie cardiaque).","src":"p. 85"},{"id":"d114-qroc-041","type":"QROC","rank":"B","objective":"d114-obj-32","tags":["paraclinique","pédiatrie"],"difficulty":2,"question":"Quels examens demande-t-on devant un syndrome de Kawasaki suspecté chez l'enfant ?","answer":"NFS, plaquettes et échographie cardiaque","accept":["nfs, plaquettes, échographie cardiaque","nfs plaquettes échographie cardiaque","nfs, plaquettes, échocardiographie"],"keywords":["nfs","plaquette","cardiaque"],"explanation":"En cas de suspicion de Kawasaki chez l'enfant : NFS, plaquettes et échographie cardiaque ; en cas de suspicion de scarlatine : NFS et prélèvement de gorge.","src":"p. 85"},{"id":"d114-qroc-042","type":"QROC","rank":"B","objective":"d114-obj-15","tags":["grossesse","étiologie"],"difficulty":2,"question":"Parmi les exanthèmes à risque chez la femme enceinte, quelle infection bactérienne expose à une forme congénitale ?","answer":"La syphilis","accept":["syphilis","la syphilis"],"keywords":["syphilis"],"explanation":"Les exanthèmes à risque chez la femme enceinte sont la rubéole (mort fœtale ou malformations), le parvovirus B19 (anasarque fœtale), la toxoplasmose et la syphilis (forme congénitale).","src":"p. 83, 85"},{"id":"d114-qroc-043","type":"QROC","rank":"B","objective":"d114-obj-11","tags":["paraclinique","biologie"],"difficulty":2,"question":"Quel antigène viral est détecté par la sérologie VIH combinée (Ag-Ac) ?","answer":"L'antigène p24","accept":["p24","antigène p24","ag p24"],"keywords":["p24"],"explanation":"Chez l'adulte, sans cause évidente, on réalise NFS, tests hépatiques, sérodiagnostic de mononucléose, test tréponémique, charge virale VIH et sérologie VIH combinée (Ag-Ac) p24.","src":"p. 85"},{"id":"d114-qroc-044","type":"QROC","rank":"B","objective":"d114-obj-24","tags":["urgence","complications"],"difficulty":2,"question":"Que faut-il rechercher devant un exanthème diffus scarlatiniforme fébrile de survenue brutale ?","answer":"Un syndrome du choc toxique staphylococcique","accept":["choc toxique staphylococcique","choc toxique","syndrome du choc toxique staphylococcique"],"keywords":["choc toxique"],"explanation":"Il faut aussi dépister des signes de retentissement hémodynamique.","src":"p. 90"},{"id":"d114-qroc-045","type":"QROC","rank":"B","objective":"d114-obj-17","tags":["étiologie"],"difficulty":2,"question":"Dans quelle proportion des cas une érythrodermie reste-t-elle idiopathique ?","answer":"10 à 15 % des cas","accept":["10 à 15 %","10-15 %","10 à 15"],"keywords":["10","15"],"explanation":"L'érythrodermie est idiopathique dans 10 à 15 % des cas ; les causes principales sont le psoriasis, la dermatite atopique, les toxidermies (DRESS) et le syndrome de Sézary.","src":"p. 91"},{"id":"d114-qcm-101","type":"QRM","rank":"A","objective":"d114-obj-01","tags":["définition","étiologie"],"difficulty":1,"stem":"Concernant les exanthèmes, quelles propositions sont exactes ?","options":[{"t":"Il s'agit d'un érythème d'apparition brutale et transitoire","ok":true,"why":"C'est la définition de l'exanthème."},{"t":"Chez l'enfant, la cause est le plus souvent virale","ok":true,"why":"Les exanthèmes fébriles de l'enfant sont le plus souvent d'origine virale."},{"t":"Chez l'adulte, la cause est exclusivement infectieuse","ok":false,"why":"Il faut aussi penser aux médicaments (toxidermie), en plus du VIH et de la syphilis."},{"t":"Il peut s'accompagner d'une atteinte muqueuse (énanthème)","ok":true,"why":"Il peut être bénin ou potentiellement grave."},{"t":"Un exanthème évolue depuis au moins 6 semaines","ok":false,"why":"Cette durée définit l'érythrodermie ; l'exanthème est transitoire."}],"explanation":"Exanthème : érythème brutal et transitoire, éventuellement avec énanthème ; causes principales infectieuses (virales chez l'enfant ; VIH, syphilis chez l'adulte) et médicamenteuses.","src":"p. 84, 90"},{"id":"d114-qcm-102","type":"QRM","rank":"A","objective":"d114-obj-03","tags":["clinique"],"difficulty":1,"stem":"Concernant les types séméiologiques d'exanthème, quelles propositions sont exactes ?","options":[{"t":"Le scarlatiniforme laisse des intervalles de peau saine entre les plaques","ok":false,"why":"Les plaques diffuses rouge vif ne laissent aucun intervalle de peau saine."},{"t":"Le morbilliforme est maculo-papuleux, confluant en plaques séparées par de la peau saine","ok":true,"why":"C'est son aspect caractéristique."},{"t":"Le roséoliforme comporte de larges plaques rouge vif confluentes","ok":false,"why":"Ce sont des macules petites, pâles et bien séparées."},{"t":"Le scarlatiniforme est fait de plaques diffuses rouge vif, granitées, plus intenses dans les plis","ok":true,"why":"Il peut évoluer vers une desquamation secondaire en larges lambeaux."},{"t":"Le roséoliforme est fait de petites macules rosées, pâles, bien séparées","ok":true,"why":"Il est aussi appelé rubéoliforme."}],"explanation":"Roséoliforme : petites macules rosées séparées. Morbilliforme : maculo-papuleux avec peau saine entre les plaques. Scarlatiniforme : plaques diffuses rouge vif sans peau saine, granitées, aux plis.","src":"p. 85"},{"id":"d114-qcm-103","type":"QRM","rank":"A","objective":"d114-obj-03","tags":["diagnostic","étiologie"],"difficulty":2,"stem":"Concernant l'orientation étiologique d'un exanthème, quelles propositions sont exactes ?","options":[{"t":"La fièvre, le syndrome grippal et les adénopathies orientent vers une origine virale","ok":true,"why":"S'y ajoute l'énanthème."},{"t":"Le caractère monomorphe de l'éruption oriente vers une toxidermie","ok":false,"why":"C'est le caractère polymorphe de l'éruption qui oriente vers une origine médicamenteuse."},{"t":"Un prurit oriente vers une origine médicamenteuse","ok":true,"why":"Avec le caractère polymorphe de l'éruption et l'hyperéosinophilie sanguine."},{"t":"Un énanthème oriente vers une origine virale","ok":true,"why":"Signe extracutané en faveur d'une origine virale."},{"t":"Une hyperéosinophilie sanguine oriente vers une origine virale","ok":false,"why":"Elle oriente vers une origine médicamenteuse."}],"explanation":"Origine virale : fièvre, syndrome grippal, énanthème, poly-adénopathie. Origine médicamenteuse : prurit, éruption polymorphe, hyperéosinophilie.","src":"p. 85"},{"id":"d114-qcm-104","type":"QRM","rank":"A","objective":"d114-obj-16","tags":["diagnostic","clinique"],"difficulty":2,"stem":"Concernant la rougeole, quelles propositions sont exactes ?","options":[{"t":"L'exanthème débute en rétro-auriculaire puis s'étend à tout le corps en une poussée","ok":true,"why":"Son aspect est morbilliforme."},{"t":"Elle est due au virus de la rubéole, comme l'exanthème roséoliforme","ok":false,"why":"Elle est due à un morbillivirus (paramyxovirus) ; le virus de la rubéole cause la rubéole."},{"t":"Elle n'est pas à déclaration obligatoire et n'impose aucune éviction","ok":false,"why":"C'est une maladie à déclaration obligatoire."},{"t":"Le signe de Köplick est un semis de papules de la face interne des joues","ok":true,"why":"Il s'observe en phase pré-éruptive."},{"t":"L'association catarrhe oculo-nasal, conjonctivite et exanthème fébrile l'évoque","ok":true,"why":"C'est l'association qui fait évoquer le diagnostic."}],"explanation":"Rougeole : morbillivirus, catarrhe oculo-nasal, conjonctivite, signe de Köplick, exanthème rétro-auriculaire puis généralisé en une poussée ; maladie à déclaration obligatoire.","src":"p. 86, 90"},{"id":"d114-qcm-105","type":"QRM","rank":"A","objective":"d114-obj-26","tags":["complications","prévention"],"difficulty":2,"stem":"Concernant les complications et la conduite à tenir devant une rougeole, quelles propositions sont exactes ?","options":[{"t":"Elle peut se compliquer d'une encéphalite","ok":true,"why":"Complication grave."},{"t":"Elle peut se compliquer d'une pneumopathie","ok":true,"why":"C'est une complication de la rougeole."},{"t":"Elle ne se complique jamais de façon grave","ok":false,"why":"Pneumopathie, encéphalite (grave), kératite et cécité sont possibles."},{"t":"L'éviction de la collectivité est inutile après la phase aiguë","ok":false,"why":"Elle est recommandée jusqu'à 5 jours après le début de l'éruption."},{"t":"Elle est à déclaration obligatoire, avec éviction jusqu'à 5 jours après le début de l'éruption","ok":true,"why":"Principes de conduite à tenir autour d'un cas."}],"explanation":"Rougeole : pneumopathie, encéphalite, kératite avec risque de cécité ; déclaration obligatoire ; éviction de la collectivité jusqu'à 5 jours après le début de l'éruption.","src":"p. 86"},{"id":"d114-qcm-106","type":"QRM","rank":"A","objective":"d114-obj-29","tags":["diagnostic","pédiatrie"],"difficulty":2,"stem":"Un nourrisson de 12 mois a une fièvre à 39,5 °C, isolée, depuis 3 jours. Une éruption de petites macules rosées pâles, bien séparées, prédominant sur le tronc apparaît ensuite. Quelles propositions sont exactes ?","options":[{"t":"Il s'agit d'une primo-infection par HHV6","ok":true,"why":"C'est la cause de l'exanthème subit."},{"t":"Il s'agit d'un exanthème subit (roséole infantile)","ok":true,"why":"Éruption roséoliforme après 3 jours de fièvre isolée chez un nourrisson."},{"t":"Il s'agit d'une rougeole, la fièvre élevée précédant l'éruption","ok":false,"why":"La rougeole associe catarrhe oculo-nasal, conjonctivite et exanthème maculo-papuleux débutant en rétro-auriculaire."},{"t":"Une scarlatine est probable : fièvre élevée puis éruption","ok":false,"why":"La scarlatine donne une angine rouge et un exanthème scarlatiniforme des grands plis."},{"t":"Aucune éviction de la collectivité n'est recommandée","ok":true,"why":"Pas de recommandation d'éviction pour l'exanthème subit."}],"explanation":"Fièvre isolée de 3 jours puis exanthème roséoliforme du tronc chez un nourrisson : exanthème subit (HHV6), sans éviction recommandée.","src":"p. 85, 90"},{"id":"d114-qcm-107","type":"QRM","rank":"A","objective":"d114-obj-27","tags":["grossesse","clinique"],"difficulty":2,"stem":"Concernant la rubéole, quelles propositions sont exactes ?","options":[{"t":"L'exanthème est roséoliforme et discret","ok":true,"why":"La rubéole figure parmi les exanthèmes roséoliformes."},{"t":"Elle expose la femme enceinte non immunisée à un risque de malformations fœtales graves","ok":true,"why":"Mort fœtale ou malformations neurologiques et sensorielles."},{"t":"L'exanthème dure en règle plusieurs semaines","ok":false,"why":"L'exanthème est discret et dure 2 à 4 jours."},{"t":"Elle est souvent asymptomatique","ok":true,"why":"Des arthralgies et une conjonctivite peuvent s'y associer."},{"t":"Elle est due au parvovirus B19 (mégalérythème épidémique)","ok":false,"why":"Elle est due au virus de la rubéole ; le parvovirus B19 cause le mégalérythème épidémique."}],"explanation":"Rubéole : exanthème roséoliforme discret, souvent asymptomatique ; danger : malformations ou mort fœtale chez la femme enceinte non immunisée.","src":"p. 85, 90"},{"id":"d114-qcm-108","type":"QRM","rank":"A","objective":"d114-obj-28","tags":["clinique","grossesse"],"difficulty":2,"stem":"Concernant le mégalérythème épidémique, quelles propositions sont exactes ?","options":[{"t":"Il est dû au parvovirus B19","ok":true,"why":"Il touche classiquement l'enfant de 5 à 10 ans."},{"t":"Il expose à un risque tératogène majeur chez la femme enceinte","ok":false,"why":"Il n'y a pas de risque tératogène ; le risque est fœtal en cas d'infection au 2e trimestre."},{"t":"Érythème-œdème des joues, érythème du tronc à bords émiettés, puis gants et chaussettes","ok":true,"why":"C'est l'évolution de l'éruption."},{"t":"La contagiosité est limitée à la phase pré-éruptive","ok":true,"why":"L'enfant n'est donc plus contagieux au moment de l'éruption."},{"t":"Une primo-infection pendant la grossesse expose au risque d'anasarque fœtale","ok":true,"why":"Avec myocardite et anémie fœtale en cas d'infection au 2e trimestre."}],"explanation":"Mégalérythème épidémique : parvovirus B19, joues, tronc à bords émiettés, gants et chaussettes ; contagiosité pré-éruptive ; risque d'anasarque fœtale (pas de risque tératogène).","src":"p. 86, 90"},{"id":"d114-qcm-109","type":"QRM","rank":"B","objective":"d114-obj-05","tags":["diagnostic","pièges"],"difficulty":2,"stem":"Un adolescent de 16 ans a une fièvre, une asthénie importante, une poly-adénopathie et une splénomégalie. Un traitement par pénicilline A est débuté, puis un exanthème apparaît. Quelles propositions sont exactes ?","options":[{"t":"La NFS montre une lymphocytose élevée avec lymphocytes hyperbasophiles","ok":true,"why":"C'est l'anomalie biologique de la mononucléose infectieuse."},{"t":"L'exanthème est un rash à l'ampicilline","ok":true,"why":"Complication classique de la mononucléose traitée par pénicilline A."},{"t":"Il ne doit pas être confondu avec une toxidermie aux pénicillines","ok":true,"why":"C'est le piège de cette situation."},{"t":"L'exanthème est constant au cours de la mononucléose infectieuse","ok":false,"why":"Il est inconstant (5 à 10 %), sauf en cas de prescription de pénicilline A."},{"t":"Le diagnostic évoqué est une mononucléose infectieuse","ok":true,"why":"Terrain adolescent, fièvre et asthénie importantes, poly-adénopathie, splénomégalie."}],"explanation":"Mononucléose infectieuse (EBV) traitée par pénicilline A : rash à l'ampicilline, à ne pas confondre avec une toxidermie ; lymphocytose avec lymphocytes hyperbasophiles.","src":"p. 82, 86"},{"id":"d114-qcm-110","type":"QRM","rank":"A","objective":"d114-obj-31","tags":["clinique","pédiatrie"],"difficulty":2,"stem":"Concernant la scarlatine, quelles propositions sont exactes ?","options":[{"t":"L'éruption prédomine aux grands plis","ok":true,"why":"Elle évolue vers une desquamation fine ou en lambeaux."},{"t":"Début brutal : fièvre, douleurs pharyngées, angine rouge, adénopathies sous-maxillaires","ok":true,"why":"Phase pré-éruptive."},{"t":"Elle est due à Staphylococcus aureus sécréteur de TSST1","ok":false,"why":"C'est le germe de la scarlatine staphylococcique, sans angine."},{"t":"Elle est due au streptocoque du groupe A","ok":true,"why":"Sécréteur d'exotoxines."},{"t":"La langue devient framboisée après une dépapillation progressive","ok":true,"why":"Dépapillation en « V » puis langue framboisée."}],"explanation":"Scarlatine : streptocoque A, début brutal avec angine, éruption des grands plis, langue framboisée, desquamation.","src":"p. 88"},{"id":"d114-qcm-111","type":"QRM","rank":"A","objective":"d114-obj-31","tags":["complications","traitement"],"difficulty":2,"stem":"Concernant le diagnostic et la prise en charge de la scarlatine, quelles propositions sont exactes ?","options":[{"t":"Un prélèvement de gorge est réalisé","ok":true,"why":"Il documente l'infection streptococcique."},{"t":"Elle peut se compliquer de glomérulonéphrite ou de rhumatisme articulaire aigu","ok":true,"why":"Ce sont les complications post-streptococciques."},{"t":"Elle expose à des anévrismes coronariens et à des troubles du rythme cardiaque","ok":false,"why":"C'est une complication du syndrome de Kawasaki."},{"t":"L'éviction scolaire dure jusqu'à 48 heures après le début du traitement","ok":true,"why":"Mesure de prévention de la transmission."},{"t":"Le traitement repose sur l'amoxicilline","ok":true,"why":"Traitement antibiotique de la scarlatine."}],"explanation":"Scarlatine : prélèvement de gorge, amoxicilline, éviction scolaire jusqu'à 48 heures après le début du traitement, complications post-streptococciques (glomérulonéphrites, RAA).","src":"p. 88"},{"id":"d114-qcm-112","type":"QRM","rank":"A","objective":"d114-obj-32","tags":["diagnostic","pédiatrie"],"difficulty":2,"stem":"Concernant le syndrome de Kawasaki, quelles propositions sont exactes ?","options":[{"t":"Il touche surtout l'enfant de moins de 5 ans","ok":true,"why":"C'est son terrain."},{"t":"C'est une vasculite systémique aiguë","ok":true,"why":"Elle est aussi appelée syndrome adéno-cutanéo-muqueux."},{"t":"Il est traité en ambulatoire par un traitement symptomatique","ok":false,"why":"L'hospitalisation est indispensable."},{"t":"La fièvre dépasse 38,5 °C depuis plus de 5 jours","ok":true,"why":"Avec altération de l'état général."},{"t":"Il est retenu si au moins cinq des six critères sont présents","ok":true,"why":"Ces critères sont cliniques."}],"explanation":"Kawasaki : vasculite systémique aiguë de l'enfant de moins de 5 ans, fièvre > 38,5 °C plus de 5 jours, au moins 5 critères sur 6, hospitalisation indispensable.","src":"p. 88"},{"id":"d114-qcm-113","type":"QRM","rank":"A","objective":"d114-obj-32","tags":["clinique","complications"],"difficulty":2,"stem":"Concernant les signes cliniques et biologiques du syndrome de Kawasaki, quelles propositions sont exactes ?","options":[{"t":"Il n'y a jamais de complication cardiaque, le pronostic est toujours bon","ok":false,"why":"Anévrismes coronariens, troubles du rythme, décès par myocardite ou infarctus sont possibles."},{"t":"Érythème et œdème des extrémités, puis desquamation en doigt de gant","ok":true,"why":"C'est l'évolution de l'atteinte des extrémités."},{"t":"Syndrome inflammatoire : CRP élevée, hyperleucocytose à PNN, thrombocytose","ok":true,"why":"Anomalies biologiques habituelles."},{"t":"Une conjonctivite bilatérale avec œdème des paupières est présente","ok":true,"why":"C'est l'un des critères."},{"t":"L'énanthème comporte une chéilite et une langue framboisée","ok":true,"why":"Atteinte caractéristique des muqueuses."}],"explanation":"Kawasaki : conjonctivite bilatérale, chéilite et langue framboisée, érythème-œdème des extrémités, exanthème polymorphe, adénopathie ; syndrome inflammatoire ; risque coronarien.","src":"p. 88"},{"id":"d114-qcm-114","type":"QRM","rank":"A","objective":"d114-obj-02","tags":["définition","clinique"],"difficulty":1,"stem":"Concernant la définition de l'érythrodermie, quelles propositions sont exactes ?","options":[{"t":"Elle touche plus de 90 % de la surface corporelle","ok":true,"why":"C'est le seuil de la définition."},{"t":"Elle associe un érythème confluant et une desquamation","ok":true,"why":"Touchant l'ensemble des téguments."},{"t":"Son aspect clinique permet de reconnaître sa cause","ok":false,"why":"L'aspect clinique ne préjuge pas de la cause."},{"t":"Elle évolue depuis au moins 6 semaines","ok":true,"why":"Une évolution prolongée est nécessaire."},{"t":"C'est un synonyme d'exanthème","ok":false,"why":"Érythrodermie n'est pas synonyme d'érythème ou d'exanthème."}],"explanation":"Érythrodermie : érythème confluant et desquamation de plus de 90 % de la surface corporelle, évoluant depuis au moins 6 semaines ; syndrome clinique aux multiples causes.","src":"p. 90, 93"},{"id":"d114-qcm-115","type":"QRM","rank":"A","objective":"d114-obj-21","tags":["clinique"],"difficulty":2,"stem":"Concernant les signes cliniques de l'érythrodermie, quelles propositions sont exactes ?","options":[{"t":"Une poly-adénopathie généralisée est fréquente","ok":true,"why":"Ganglions parfois volumineux, souples et mobiles."},{"t":"Le prurit est constant","ok":true,"why":"Il est associé à la desquamation constante."},{"t":"Une dysrégulation thermique cutanée peut donner des épisodes de fièvre et d'hypothermie","ok":true,"why":"Signe de la dysrégulation thermique importante."},{"t":"L'érythème est généralisé, inflammatoire, plus violacé aux zones déclives","ok":true,"why":"Son intensité varie d'un jour à l'autre."},{"t":"Une atteinte des phanères (chute des cheveux, ongles dystrophiques) est précoce, dès les premiers jours","ok":false,"why":"Elle apparaît après quelques semaines d'évolution."}],"explanation":"Érythrodermie : érythème généralisé violacé aux zones déclives, desquamation et prurit constants, dysrégulation thermique, œdème du visage, poly-adénopathie ; phanères atteints après quelques semaines.","src":"p. 90-91"},{"id":"d114-qcm-116","type":"QRM","rank":"A","objective":"d114-obj-06","tags":["complications"],"difficulty":2,"stem":"Concernant les complications de l'érythrodermie, quelles propositions sont exactes ?","options":[{"t":"Infections cutanées bactériennes (staphylocoque) ou virales (herpès, varicelle-zona)","ok":true,"why":"Des infections générales (pneumopathies, septicémies) sont possibles."},{"t":"La mortalité peut atteindre 20 %","ok":true,"why":"Elle est liée aux complications, notamment infectieuses."},{"t":"La déperdition hydro-électrolytique peut décompenser une insuffisance cardiaque, respiratoire ou rénale","ok":true,"why":"Elle résulte de la vasodilatation cutanée, de la desquamation, du suintement, de l'œdème et de la fièvre."},{"t":"La gravité est indépendante du terrain et des complications","ok":false,"why":"Elle est corrélée au terrain et aux complications."},{"t":"Le décubitus expose à la dénutrition, à la cachexie et aux escarres","ok":true,"why":"Ces complications sont à prendre rapidement en charge."}],"explanation":"Complications : déperdition hydro-électrolytique, décubitus, infections, décès (mortalité jusqu'à 20 %) ; la gravité dépend du terrain.","src":"p. 92-93"},{"id":"d114-qcm-117","type":"QRM","rank":"A","objective":"d114-obj-09","tags":["urgence","traitement"],"difficulty":2,"stem":"Concernant la prise en charge d'une érythrodermie, quelles propositions sont exactes ?","options":[{"t":"Une hospitalisation en urgence est nécessaire","ok":true,"why":"C'est une urgence dermatologique."},{"t":"Le réchauffement du malade limite les pertes caloriques et la dénutrition","ok":true,"why":"Il limite aussi l'hypercatabolisme."},{"t":"Les troubles hydro-électrolytiques sont rééquilibrés","ok":true,"why":"Avec traitement des éventuelles défaillances viscérales."},{"t":"Une prise en charge ambulatoire est possible avec surveillance à domicile","ok":false,"why":"Une érythrodermie nécessite une hospitalisation urgente."},{"t":"Dans les formes graves, une corticothérapie locale très forte améliore les symptômes","ok":true,"why":"Il s'agit d'un traitement symptomatique."}],"explanation":"Érythrodermie : hospitalisation en urgence, examens de gravité, rééquilibration hydro-électrolytique, recherche étiologique, réchauffement, corticothérapie locale très forte dans les formes graves.","src":"p. 90, 93"},{"id":"d114-qcm-118","type":"QRM","rank":"A","objective":"d114-obj-17","tags":["étiologie"],"difficulty":2,"stem":"Quelles sont des causes d'érythrodermie de l'adulte ?","options":[{"t":"Le psoriasis","ok":true,"why":"Cause principale."},{"t":"Une toxidermie de type DRESS","ok":true,"why":"Cause principale."},{"t":"Le syndrome de Sézary","ok":true,"why":"Lymphome T cutané épidermotrope."},{"t":"Une nécrolyse épidermique aiguë avec décollement","ok":false,"why":"Un exanthème ou une nécrolyse épidermique d'évolution aiguë ne sont pas des érythrodermies."},{"t":"La dermatite atopique","ok":true,"why":"Cause principale."}],"explanation":"Les principales causes d'érythrodermie sont le psoriasis, la dermatite atopique, le lymphome cutané (syndrome de Sézary) et la toxidermie (DRESS).","src":"p. 90-91, 93"},{"id":"d114-qcm-119","type":"QRM","rank":"B","objective":"d114-obj-25","tags":["paraclinique","diagnostic"],"difficulty":2,"stem":"Concernant les examens complémentaires devant un exanthème, quelles propositions sont exactes ?","options":[{"t":"Chez l'enfant, une sérologie VIH est indispensable dans tous les cas d'exanthème","ok":false,"why":"Aucun examen n'est indispensable chez l'enfant, sauf suspicion de scarlatine ou de Kawasaki."},{"t":"Chez l'adulte sans cause évidente : test tréponémique, charge virale VIH et sérologie VIH combinée","ok":true,"why":"Avec NFS, tests hépatiques et sérodiagnostic de mononucléose."},{"t":"En cas de suspicion de Kawasaki : NFS, plaquettes et échographie cardiaque","ok":true,"why":"Recherche d'un syndrome inflammatoire et d'une atteinte cardiaque."},{"t":"Chez la femme enceinte : sérologies de toxoplasmose, rubéole, CMV, parvovirus B19 et syphilis","ok":true,"why":"En tenant compte de son statut sérologique de début de grossesse."},{"t":"Chez l'enfant, aucun examen indispensable sauf suspicion de scarlatine ou de Kawasaki","ok":true,"why":"Pour une scarlatine : NFS et prélèvement de gorge."}],"explanation":"Enfant : aucun examen sauf scarlatine ou Kawasaki. Adulte : NFS, tests hépatiques, mononucléose, tréponème, VIH. Femme enceinte : toxoplasmose, rubéole, CMV, parvovirus B19, syphilis.","src":"p. 85"},{"id":"d114-qcm-120","type":"QRM","rank":"B","objective":"d114-obj-13","tags":["étiologie","diagnostic"],"difficulty":2,"stem":"Concernant les causes principales d'exanthème selon leur type séméiologique, quelles propositions sont exactes ?","options":[{"t":"Exanthème scarlatiniforme : scarlatine, syndrome de Kawasaki","ok":true,"why":"Ce sont les deux causes principales de l'exanthème scarlatiniforme."},{"t":"Exanthème roséoliforme : exanthème subit, rubéole, primo-infection VIH, syphilis secondaire","ok":true,"why":"Ce sont les quatre causes principales de l'exanthème roséoliforme."},{"t":"La rougeole est une cause principale d'exanthème scarlatiniforme","ok":false,"why":"Elle donne un exanthème morbilliforme."},{"t":"Exanthème morbilliforme : rougeole, mégalérythème épidémique, mononucléose infectieuse","ok":true,"why":"Ce sont les trois causes principales de l'exanthème morbilliforme."},{"t":"La rubéole est une cause principale d'exanthème morbilliforme","ok":false,"why":"Elle donne un exanthème roséoliforme."}],"explanation":"Roséoliforme : exanthème subit, rubéole, primo-infection VIH, syphilis secondaire. Morbilliforme : rougeole, mégalérythème épidémique, mononucléose infectieuse. Scarlatiniforme : scarlatine, syndrome de Kawasaki.","src":"p. 83, 85-86, 88"},{"id":"d114-qru-101","type":"QRU","rank":"A","objective":"d114-obj-20","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Un enfant fébrile présente des plaques rouge vif diffuses, légèrement granitées, sans intervalle de peau saine, s'intensifiant dans les plis. Quel type d'exanthème est décrit ?","options":[{"t":"Roséoliforme","ok":false,"why":"Il est fait de petites macules rosées, pâles, bien séparées."},{"t":"Rubéoliforme","ok":false,"why":"C'est un synonyme de roséoliforme : petites macules rosées bien séparées."},{"t":"Érythrodermique","ok":false,"why":"L'érythrodermie évolue depuis au moins 6 semaines et touche plus de 90 % de la surface corporelle."},{"t":"Morbilliforme","ok":false,"why":"Il est maculo-papuleux, avec des plaques séparées par de la peau saine."},{"t":"Scarlatiniforme","ok":true,"why":"Plaques diffuses rouge vif sans peau saine intercalée, granitées, s'intensifiant dans les plis."}],"explanation":"Plaques diffuses rouge vif, granitées, sans intervalle de peau saine, plus intenses dans les plis : exanthème scarlatiniforme.","src":"p. 85"},{"id":"d114-qru-102","type":"QRU","rank":"A","objective":"d114-obj-26","tags":["diagnostic","pédiatrie"],"difficulty":2,"stem":"Un enfant de 6 ans a une fièvre à 39,5 °C avec un catarrhe oculo-nasal et une conjonctivite. Un exanthème maculo-papuleux débute en région rétro-auriculaire et gagne tout le corps. Quel est le diagnostic ?","options":[{"t":"Une rubéole","ok":false,"why":"Son exanthème est discret (2 à 4 jours), souvent avec peu de symptômes."},{"t":"Un mégalérythème épidémique","ok":false,"why":"Il donne un érythème des joues, puis un érythème en gants et chaussettes."},{"t":"Une scarlatine","ok":false,"why":"Elle associe angine rouge, éruption des grands plis et langue framboisée."},{"t":"Une rougeole","ok":true,"why":"Catarrhe oculo-nasal, conjonctivite et exanthème fébrile, avec progression rétro-auriculaire."},{"t":"Un exanthème subit","ok":false,"why":"Il survient chez le nourrisson, après 3 jours de fièvre isolée."}],"explanation":"Catarrhe oculo-nasal, conjonctivite, fièvre élevée et exanthème partant de la région rétro-auriculaire : rougeole.","src":"p. 85-86, 90"},{"id":"d114-qru-103","type":"QRU","rank":"A","objective":"d114-obj-28","tags":["étiologie","pédiatrie"],"difficulty":2,"stem":"Un enfant de 7 ans, peu fébrile, présente un érythème et un œdème des joues, puis un érythème du tronc à bords émiettés et un érythème en gants et chaussettes. Quel est l'agent responsable ?","options":[{"t":"Le virus de la rubéole","ok":false,"why":"Il donne un exanthème roséoliforme discret chez l'adolescent ou l'adulte jeune."},{"t":"Le parvovirus B19","ok":true,"why":"Agent du mégalérythème épidémique."},{"t":"Le morbillivirus","ok":false,"why":"Il cause la rougeole, avec catarrhe oculo-nasal et conjonctivite."},{"t":"Le streptocoque du groupe A","ok":false,"why":"Il cause la scarlatine, avec angine rouge et éruption des grands plis."},{"t":"Le virus d'Epstein-Barr","ok":false,"why":"Il cause la mononucléose infectieuse de l'adolescent."}],"explanation":"Joues œdémateuses érythémateuses, érythème du tronc à bords émiettés puis gants et chaussettes : mégalérythème épidémique, dû au parvovirus B19.","src":"p. 86"},{"id":"d114-qru-104","type":"QRU","rank":"A","objective":"d114-obj-31","tags":["diagnostic","pédiatrie"],"difficulty":2,"stem":"Un enfant de 7 ans a un début brutal avec une fièvre à 39,5 °C, des douleurs pharyngées, une angine rouge et des adénopathies sous-maxillaires. Une éruption des grands plis et une langue framboisée apparaissent ensuite. Quel est le diagnostic ?","options":[{"t":"Une scarlatine","ok":true,"why":"Streptocoque A : angine rouge, éruption des grands plis, langue framboisée."},{"t":"Une rougeole","ok":false,"why":"Elle associe catarrhe oculo-nasal, conjonctivite et exanthème maculo-papuleux."},{"t":"Une scarlatine staphylococcique","ok":false,"why":"Elle se caractérise par une absence d'angine."},{"t":"Un syndrome de Kawasaki","ok":false,"why":"Il donne une fièvre de plus de 5 jours, avec conjonctivite bilatérale, chéilite et atteinte des extrémités."},{"t":"Une rubéole","ok":false,"why":"Elle donne un exanthème roséoliforme discret, sans angine."}],"explanation":"Angine rouge, adénopathies sous-maxillaires, éruption des grands plis et langue framboisée : scarlatine streptococcique.","src":"p. 88"},{"id":"d114-qru-105","type":"QRU","rank":"A","objective":"d114-obj-32","tags":["complications","pédiatrie"],"difficulty":2,"stem":"Un enfant de 3 ans a une fièvre à 39 °C depuis 6 jours, avec une conjonctivite bilatérale et un œdème des paupières, une chéilite, une langue framboisée, un érythème et un œdème des extrémités, et un exanthème polymorphe. Quelle complication redoute-t-on ?","options":[{"t":"Une rupture splénique","ok":false,"why":"C'est une complication rare de la mononucléose infectieuse."},{"t":"Une kératite avec cécité","ok":false,"why":"C'est une complication de la rougeole."},{"t":"Une anasarque fœtale","ok":false,"why":"C'est un risque lié au parvovirus B19 pendant la grossesse."},{"t":"Une glomérulonéphrite","ok":false,"why":"C'est une complication post-streptococcique de la scarlatine."},{"t":"Des anévrismes coronariens","ok":true,"why":"Complication du syndrome de Kawasaki, d'où l'hospitalisation indispensable."}],"explanation":"Fièvre de plus de 5 jours avec plusieurs critères cliniques : syndrome de Kawasaki, avec risque d'anévrismes coronariens.","src":"p. 88, 90"},{"id":"d114-qru-106","type":"QRU","rank":"A","objective":"d114-obj-28","tags":["grossesse","étiologie"],"difficulty":1,"stem":"Quelle primo-infection survenant pendant la grossesse expose au risque d'anasarque fœtale ?","options":[{"t":"La rubéole","ok":false,"why":"Elle expose à une mort fœtale ou à des malformations."},{"t":"L'exanthème subit (HHV6)","ok":false,"why":"Ses complications sont rares (convulsions fébriles, méningite virale...)."},{"t":"La mononucléose infectieuse","ok":false,"why":"Ses complications rares sont hépatiques, neurologiques, spléniques et hématologiques."},{"t":"La rougeole","ok":false,"why":"Elle se complique de pneumopathie, d'encéphalite ou de kératite."},{"t":"Le parvovirus B19","ok":true,"why":"Pas de risque tératogène, mais risque d'anasarque fœtale, de myocardite et d'anémie fœtale."}],"explanation":"La primo-infection à parvovirus B19 pendant la grossesse expose au risque d'anasarque fœtale.","src":"p. 86, 90"},{"id":"d114-qru-107","type":"QRU","rank":"A","objective":"d114-obj-09","tags":["urgence","diagnostic"],"difficulty":2,"stem":"Un homme de 60 ans présente depuis 2 mois un érythème généralisé desquamatif et prurigineux, avec une poly-adénopathie et des épisodes de fièvre et d'hypothermie. Quelle est la prise en charge initiale ?","options":[{"t":"Un traitement ambulatoire par dermocorticoïde","ok":false,"why":"Une érythrodermie nécessite une hospitalisation urgente."},{"t":"Une consultation de contrôle à 1 mois","ok":false,"why":"Il s'agit d'une urgence dermatologique."},{"t":"Une antibiothérapie probabiliste à domicile","ok":false,"why":"L'hospitalisation s'impose ; une infection est à rechercher et à traiter."},{"t":"Une hospitalisation en urgence","ok":true,"why":"Bilan de gravité, rééquilibration hydro-électrolytique et recherche étiologique."},{"t":"Une simple surveillance sans bilan","ok":false,"why":"La recherche étiologique est immédiate."}],"explanation":"Érythème généralisé desquamatif évoluant depuis plus de 6 semaines : érythrodermie, urgence imposant l'hospitalisation.","src":"p. 90, 93"},{"id":"d114-qru-108","type":"QRU","rank":"B","objective":"d114-obj-07","tags":["urgence","diagnostic"],"difficulty":3,"stem":"Un adolescent de 17 ans présente brutalement une fièvre élevée et un exanthème diffus scarlatiniforme. Il est tachycarde et hypotendu. Quel diagnostic grave faut-il rechercher ?","options":[{"t":"Une rougeole compliquée d'une pneumopathie","ok":false,"why":"Elle donne un exanthème maculo-papuleux avec catarrhe oculo-nasal et conjonctivite."},{"t":"Un exanthème subit (roséole infantile)","ok":false,"why":"Il survient chez le nourrisson de 6 à 18 mois."},{"t":"Un syndrome du choc toxique staphylococcique","ok":true,"why":"Un exanthème scarlatiniforme fébrile brutal doit le faire rechercher, avec dépistage du retentissement hémodynamique."},{"t":"Un mégalérythème épidémique à parvovirus B19","ok":false,"why":"Il touche l'enfant de 5 à 10 ans, avec un érythème des joues."},{"t":"Un syndrome de Kawasaki (vasculite systémique aiguë)","ok":false,"why":"Il touche l'enfant de moins de 5 ans."}],"explanation":"Un exanthème diffus scarlatiniforme fébrile de survenue brutale doit faire rechercher un syndrome du choc toxique staphylococcique et un retentissement hémodynamique.","src":"p. 88, 90"}],"edn":[],"trees":[],"treatments":{"data":[],"strategies":[]},"cases":[],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":null,"pareto":{"id":"d114-pareto","points":[{"id":"d114-par-01","rank":"A","cat":"définition","text":"**Exanthème** = érythème d'apparition **brutale et transitoire** (± énanthème) ; causes : **virales** (enfant), **VIH/syphilis** et **médicaments** (adulte)","src":"p. 84, 90"},{"id":"d114-par-02","rank":"A","cat":"clinique","text":"3 types : **roséoliforme** (petites macules rosées séparées), **morbilliforme** (maculo-papuleux, peau saine entre les plaques), **scarlatiniforme** (rouge vif, **sans peau saine**, plis)","src":"p. 85"},{"id":"d114-par-03","rank":"A","cat":"clinique","text":"Origine **virale** : fièvre, syndrome grippal, énanthème, adénopathies ; origine **médicamenteuse** : **prurit**, éruption polymorphe, **hyperéosinophilie**","src":"p. 85"},{"id":"d114-par-04","rank":"A","cat":"clinique","text":"**Rougeole** : catarrhe oculo-nasal + conjonctivite + exanthème fébrile ; **signe de Köplick** ; début rétro-auriculaire ; complications : pneumopathie, **encéphalite**, kératite","src":"p. 86, 90"},{"id":"d114-par-05","rank":"A","cat":"prévention","text":"Rougeole = maladie à **déclaration obligatoire** ; éviction de la collectivité jusqu'à **5 jours** après le début de l'éruption","src":"p. 86"},{"id":"d114-par-06","rank":"A","cat":"clinique","text":"**Exanthème subit** : nourrisson, **HHV6**, fièvre isolée **3 jours** puis éruption roséoliforme du tronc ; pas d'éviction de la collectivité","src":"p. 85, 90"},{"id":"d114-par-07","rank":"A","cat":"gravité","text":"Grossesse : **rubéole** → **malformations**/mort fœtale ; **parvovirus B19** (mégalérythème épidémique) → **anasarque fœtale**, pas de risque tératogène","src":"p. 85-86, 90"},{"id":"d114-par-08","rank":"A","cat":"clinique","text":"**Mégalérythème épidémique** (parvovirus B19, enfant 5-10 ans) : érythème-œdème des joues, tronc à bords émiettés, puis **gants et chaussettes** ; contagiosité pré-éruptive","src":"p. 86"},{"id":"d114-par-09","rank":"A","cat":"piège","text":"**MNI** (EBV, adolescent) : **lymphocytes hyperbasophiles** ; exanthème inconstant sauf **pénicilline A** → **rash à l'ampicilline**, à ne pas confondre avec une toxidermie","src":"p. 82, 86"},{"id":"d114-par-10","rank":"A","cat":"clinique","text":"**Scarlatine** : streptocoque A, début brutal + angine, grands plis, **langue framboisée** ; prélèvement de gorge, **amoxicilline**, éviction 48 h ; complications **GNA/RAA**","src":"p. 88"},{"id":"d114-par-11","rank":"A","cat":"gravité","text":"**Kawasaki** : vasculite, enfant < 5 ans, fièvre > 38,5 °C **> 5 jours**, **≥ 5 critères sur 6** ; risque d'**anévrismes coronariens** ; **hospitalisation** indispensable","src":"p. 88, 90"},{"id":"d114-par-12","rank":"B","cat":"piège","text":"Scarlatine **staphylococcique** : **pas d'angine**, grands plis puis décollement bulleux, **oxacilline** ; exanthème scarlatiniforme brutal fébrile → chercher un **choc toxique**","src":"p. 88, 90"},{"id":"d114-par-13","rank":"A","cat":"définition","text":"**Érythrodermie** = érythème + desquamation > **90 %** de la surface, depuis ≥ **6 semaines** ; prurit constant, **dysrégulation thermique** ; ≠ exanthème ; **urgence**","src":"p. 90-91, 93"},{"id":"d114-par-14","rank":"A","cat":"étiologie","text":"Causes d'érythrodermie : **psoriasis**, **dermatite atopique**, **DRESS**, **syndrome de Sézary** ; mortalité jusqu'à **20 %** (troubles hydro-électrolytiques, escarres, infections)","src":"p. 91-93"},{"id":"d114-par-15","rank":"A","cat":"traitement","text":"Érythrodermie : **hospitalisation en urgence**, **rééquilibration hydro-électrolytique**, **réchauffement**, recherche étiologique, corticothérapie locale de niveau 1 si forme grave","src":"p. 90, 93"}]},"extra":{"semio":[],"criteres":[],"chiffres":[],"physio":[],"parcours":[],"examens":[]}});
